window.PATHOLOGY_EXPLANATIONS = {"version":1,"language":"zh-CN","entries":{"pathology-ch01-en-single-001":{"text":"生殖细胞的端粒酶可维持染色体末端长度，支持持续增殖，故选生殖细胞。成熟神经元通常不再分裂，成熟红细胞没有细胞核，两者均不符合高端粒酶活性的典型情形。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-002":{"text":"骨折后大腿长期制动减少肌肉负荷，肌细胞体积和肌肉横截面积下降，属于废用性萎缩。 与坏死或发育不全的机制不同。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-003":{"text":"左心衰使肺静脉压升高，红细胞漏入肺泡后被巨噬细胞吞噬；含铁血黄素巨噬细胞即“心衰细胞”。 巨噬细胞内铁来自吞噬后的血红蛋白。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-004":{"text":"开放伤常经历肉芽组织形成、上皮迁移和伤口收缩。巨细胞通常提示异物反应，并非每个伤口愈合都必然出现。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-005":{"text":"维生素K主要参与凝血因子活化，并非伤口修复的关键限制因素；饥饿、激素、缺血和感染都会妨碍愈合。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-006":{"text":"糖皮质激素抑制炎症并减少胶原合成，可能延缓伤口修复；氧、锌、维生素C和生长因子有助修复。 尤其不利于胶原沉积和伤口强度恢复。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-007":{"text":"脑梗死后坏死组织被酶消化，形成液化坏死和囊腔；脑组织梗死不同于心肌等器官常见的凝固性坏死。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-008":{"text":"一期愈合切口以炎症清除、细胞增生和基质重塑为主；明显收缩主要见于开放创面二期愈合。 因此切口通常不会明显向中心收缩。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-009":{"text":"糖尿病、低丙种球蛋白和粒细胞缺乏可增加感染风险。原题选嗜酸性粒细胞增多作为例外，但血小板减少主要影响止血，并非同类典型免疫缺陷；此题对感染与愈合风险的分类不够严谨，待复核。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch01-en-single-010":{"text":"三色染色阳性的蓝色纤维物质符合胶原瘢痕。胶原由成纤维细胞合成，富含甘氨酸和羟脯氨酸。 这与肝源白蛋白或血浆细胞抗体不同。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-011":{"text":"新生血管内皮细胞的增殖和迁移主要受VEGF促进；PDGF更多募集并刺激成纤维细胞和周细胞。 VEGF还可提高新生血管通透性。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-012":{"text":"肝细胞再生受限时，门管区肝祖细胞可形成卵圆细胞，并分化为肝细胞或胆管上皮。 卵圆细胞是肝内祖细胞群。","references":[{"title":"Liver development: regeneration and adult hepatic stem cells","url":"https://www.ncbi.nlm.nih.gov/books/NBK27068/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-013":{"text":"胚胎干细胞可在体外进行靶基因改造，再参与胚胎形成嵌合小鼠，是经典基因敲除造模方法。 改造后的细胞可进入胚胎各组织。","references":[{"title":"Studying Gene Expression and Function","url":"https://www.ncbi.nlm.nih.gov/books/NBK26818/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-014":{"text":"肝炎恢复且转氨酶回归正常后，多数肝细胞已退出增殖周期并回到静止期G0。 G0表示暂时退出细胞周期。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-015":{"text":"切片显示大量蓝染、排列致密的胶原，提示瘢痕已进入成熟重塑期；缝合切口术后约一个月可见此类胶原瘢痕。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-016":{"text":"瘢痕持续隆起并呈结节状，符合瘢痕疙瘩形成；它是胶原过度沉积，且常超出原伤口边界。 它不同于局限于原切口的增生性瘢痕。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-017":{"text":"纤维连接蛋白可结合胶原和细胞整合素，形成细胞与细胞外基质之间的黏附桥，并帮助基底细胞附着基底膜。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-018":{"text":"肠系膜脂肪内多发白色皂化斑符合急性胰腺炎的酶性脂肪坏死；脂肪酶释放会造成脂肪酸与钙结合。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-019":{"text":"整合素是跨膜受体，胞外结合基质、胞内连接细胞骨架，因而能传递细胞与基质之间的机械和信号联系。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-020":{"text":"二期愈合开放创面缩小主要靠肌成纤维细胞收缩。胶原沉积增强强度，但不是伤口面积缩小的直接主因。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-021":{"text":"术后一周切口仍在增生修复阶段，肉芽组织尚可见；此时胶原强度远未恢复到正常组织水平。 瘢痕强度之后仍会随胶原重塑增加。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-022":{"text":"肝组织支架完整时肝细胞再生可恢复结构；细菌脓肿破坏结缔组织框架后更易由胶原瘢痕修复。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-023":{"text":"心肌细胞再生能力有限，梗死一个月后坏死区已被肉芽组织替代并形成纤维瘢痕，而非恢复为正常心肌。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-024":{"text":"TGF-β促进成纤维细胞表达胶原和其他基质成分；中和后最直接受影响的是胶原生成及瘢痕基质沉积。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-025":{"text":"脑组织梗死后发生液化坏死，源于酶解作用和脑组织结构特点；心、肾、肝和脾梗死通常呈凝固性坏死。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-026":{"text":"坏疽是大范围组织坏死并伴腐败分解的临床形态描述；感染常参与湿性坏疽，但并非定义的必需条件。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-027":{"text":"刚果红可与淀粉样纤维结合，偏振光下呈苹果绿双折射；这是识别组织淀粉样沉积的经典染色表现。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-028":{"text":"原发性AL型淀粉样蛋白由免疫球蛋白轻链形成；选项中的免疫球蛋白最符合其来源。 轻链可错误折叠并形成淀粉样纤维。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-029":{"text":"动脉粥样斑块中的胆固醇溶出后留下细长裂隙样空隙；脂褐素和含铁血黄素呈颗粒沉积，不呈此形态。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-030":{"text":"系统性淀粉样沉积常累及肾、肝和脾，肺相对少见；肺也可有局限性淀粉样沉积，故此题比较的是相对频率。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-031":{"text":"标准病理学中肾脏是转移性钙化的常见部位；甲状腺乳头状癌中的砂粒体通常属局部营养不良性钙化。原答案E与此冲突，需核对题目或答案。","references":[{"title":"Calcinosis Cutis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK448127/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch01-en-single-032":{"text":"Bence-Jones蛋白是单克隆免疫球蛋白游离轻链，可由尿中检出，常见于多发性骨髓瘤。 轻链经肾小球滤过后随尿排出。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-033":{"text":"中枢神经系统成熟神经元及其组织缺乏发生典型上皮化生的细胞基础；呼吸、消化及尿路上皮则可见化生。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-034":{"text":"饥饿时脂肪、肝脏和骨骼肌等储能或代谢组织会缩小；骨骼并非典型的早期能量储备消耗部位。 此处问的是饥饿性萎缩的相对保留组织。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-035":{"text":"衰老可导致骨、肾、骨髓和脑组织萎缩；外周血是循环细胞成分，不是典型发生组织萎缩的实质器官。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-036":{"text":"肥大指单个细胞体积增大，使组织整体体积增加；细胞数量增加才称为增生。 肥大常由功能负荷增加所致。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-037":{"text":"关节固定后肌肉收缩活动和负荷减少，肌纤维逐渐缩小，构成典型废用性萎缩。 题干明确给出固定关节这一诱因。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-038":{"text":"多发性骨髓瘤通常产生AL型原发淀粉样变；AA型继发淀粉样变可见于类风湿关节炎和家族性地中海热。选项A、E均可成立，答案D不符，需复核单选题。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch01-en-single-039":{"text":"多发性骨髓瘤伴肾小球刚果红阳性沉积提示AL淀粉样变，其前体为克隆浆细胞产生的免疫球蛋白轻链。","references":[{"title":"Amyloidosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470285/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-040":{"text":"长期受损的主动脉瓣发生局部钙盐沉积而血钙未必升高，属于营养不良性钙化；与软组织广泛转移性钙化不同。","references":[{"title":"Calcinosis Cutis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK448127/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-041":{"text":"左心衰造成肺淤血和肺泡出血，肺泡巨噬细胞吞噬红细胞并储存含铁血黄素，形成心衰细胞。 吞噬铁后的巨噬细胞呈棕黄色颗粒。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-042":{"text":"Fas受体结合配体后招募FADD，进而激活起始型caspase-8，启动外源性凋亡通路。 FADD连接受体信号与起始型半胱天冬酶。","references":[{"title":"Regulation of Programmed Cell Death - The Cell","url":"https://www.ncbi.nlm.nih.gov/books/NBK9922/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-043":{"text":"化脓性细菌感染产生大量酶，脑梗死组织也易被消化液化，因此两者典型地表现为液化性坏死。 两种情境均有组织被酶性消化的特点。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-044":{"text":"Councilman小体是凋亡的肝细胞。细胞皱缩并形成膜包裹小体，内容物不大量外泄，因此炎症反应轻微。 凋亡小体随后由吞噬细胞清除。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch01-en-single-045":{"text":"砂粒体是肿瘤或坏死组织内局灶钙盐沉积，血钙通常正常，属于营养不良性钙化。 局部组织病变可提供钙盐沉积核心。","references":[{"title":"Calcinosis Cutis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK448127/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-046":{"text":"酒精性肝炎的Mallory-Denk小体由角蛋白中间丝聚集形成；题目称作prekeratin，指向同一类细胞骨架蛋白。 角蛋白聚集也可见于其他慢性肝病。","references":[{"title":"Mallory Bodies - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK545300/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-047":{"text":"普鲁士蓝与组织中的三价铁反应呈蓝色，可显示肝细胞内含铁血黄素；脂质染色不能证明铁沉积。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-048":{"text":"不可逆损伤心肌线粒体内的大型絮状致密物提示严重线粒体损伤；溶栓后的再灌注也可增加心肌损害。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-049":{"text":"长期饮酒可导致肝细胞脂肪变，甘油三酯在胞质积聚；常规制片时脂质溶出，留下透明空泡。 这是肝细胞脂肪变的典型制片表现。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-050":{"text":"泛素可标记错误折叠或受损蛋白，随后由胞质蛋白酶体识别并降解；紫外线损伤会增加这类蛋白。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-051":{"text":"长期高血压增加左心室后负荷，心肌细胞通过增大体积适应压力负荷，故出现心肌肥大。 这是压力负荷下心肌的适应性改变。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-052":{"text":"肺泡巨噬细胞内吞红细胞后，溶酶体分解血红蛋白并留下含铁血黄素；因此溶酶体参与其形成。 吞噬物在溶酶体内被分解处理。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-053":{"text":"妊娠期子宫扩大主要由肌层平滑肌细胞肥大造成，也可伴有增生；题目所列最主要机制是细胞体积增加。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-054":{"text":"结核分枝杆菌感染的肺结节典型出现干酪样坏死，肉眼呈白色、干酪样，区别于液化性或脂肪坏死。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-055":{"text":"BCL-2抑制线粒体凋亡通路；其失活会解除对凋亡的抑制，使细胞皱缩、染色质凝集和膜起泡增多。 凋亡抑制因子失活可增加细胞死亡。","references":[{"title":"Regulation of Programmed Cell Death - The Cell","url":"https://www.ncbi.nlm.nih.gov/books/NBK9922/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-056":{"text":"高钙血症和肾小管钙盐沉积提示转移性钙化，发生于血钙或磷酸盐代谢异常，不要求组织先坏死。","references":[{"title":"Calcinosis Cutis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK448127/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-057":{"text":"长期吸烟吸入的碳颗粒由肺泡巨噬细胞吞噬，再经淋巴引流到肺门淋巴结，形成黑色炭末沉着。 此类碳颗粒沉积称为炭末沉着。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-058":{"text":"老年萎缩心肌呈棕褐色，常因脂褐素在细胞内累积，称为棕色萎缩；它不是铁或胆红素沉积。 脂褐素是长期氧化损伤后的残余物。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-059":{"text":"皮肤切片可见角质形成细胞凋亡小体；移植物抗宿主反应诱发细胞凋亡，其执行阶段由caspase介导。 细胞皱缩和核碎裂也是凋亡形态线索。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-060":{"text":"长期饮酒可造成肝细胞脂肪变，使肝脏增大并呈黄色；白蛋白下降和凝血酶原时间延长还提示合成功能受损。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-061":{"text":"左房血栓脱落进入肾动脉造成肾梗死；肾等实质器官缺血后典型发生凝固性坏死。 肾脏梗死保留组织轮廓一段时间。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-062":{"text":"切除部分肝叶后，残存肝细胞增殖补足肝脏体积，属于代偿性增生，而非细胞单纯肥大。 肝脏恢复的是质量和体积，不是原切除叶。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch01-en-single-063":{"text":"慢性肾小球肾炎可引起磷潴留和继发性甲旁亢，改变钙磷平衡，促使正常组织出现转移性钙化。 这种钙盐沉积发生在原本正常组织。","references":[{"title":"Calcinosis Cutis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK448127/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-064":{"text":"细胞核碎裂是不可逆细胞损伤和坏死的典型核改变；线粒体肿胀或膜起泡也可见于较早期损伤。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-065":{"text":"t-PA溶解冠脉血栓并恢复供血后，活性氧和炎症反应可造成额外细胞损害，使肌酸激酶释放增加。 肌酸激酶升高反映心肌细胞内容物漏出。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch01-en-single-066":{"text":"老年男性前列腺腺体和间质结节性增多，符合良性前列腺增生；它不是细胞体积增大的肥大。 结节由腺体和间质共同增生形成。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch01-en-single-067":{"text":"冠状动脉血栓导致心肌缺血，出现胞质嗜酸性增强和细胞核消失，符合心肌凝固性坏死。 缺血性心肌坏死通常保留组织轮廓。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch01-en-single-068":{"text":"多年输血造成铁负荷过多，铁以含铁血黄素形式沉积在肝细胞；可用铁染色进一步显示。 反复输血是继发性铁过载的重要来源。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-001":{"text":"止血是血栓形成的生理性局部反应，可封闭血管损伤，并非血栓的不良后果；血管阻塞和栓塞则是病理后果。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-002":{"text":"血栓可溶解、机化、再通或脱落栓塞。梗死是血栓造成的组织后果，不是血栓本身的演变结局。 只有梗死是血栓造成的下游并发症。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"},{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-003":{"text":"纤维蛋白降解产物抑制凝血并提示纤溶，不是促栓因素；其余选项可造成血流异常或凝血倾向。 它反而可减弱凝血酶作用。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-004":{"text":"睾丸扭转先阻断静脉回流，造成淤血和出血性梗死；动脉供血可暂时保留。 静脉阻断还会加重组织出血。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-005":{"text":"脑梗死典型发生液化坏死，因为脑组织脂质丰富、支架薄弱，坏死区易被酶消化。 坏死细胞被酶性消化是关键。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-006":{"text":"肺梗死常呈靠近胸膜的楔形，但并非每例都必然如此；题干“always”过于绝对，原答案A需结合教材表述复核。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch02-en-single-007":{"text":"肺和小肠具双重血供或丰富吻合支，静脉阻塞也可出血，故梗死常呈红色而非贫血性。 组织疏松和双重血供促成红色外观。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-008":{"text":"多数梗死由动脉内血栓或栓子堵塞供血造成；血管痉挛、外压或斑块内出血相对少见。 这是最常见的血管阻塞方式。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"},{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-009":{"text":"最常见的栓塞类型是血栓栓塞，即血栓脱落后随血流到达远端血管并阻塞。 气体、脂肪和肿瘤栓相对少见。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"},{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-010":{"text":"肺有肺动脉和支气管动脉双重供血，肺泡氧也可扩散入组织，因此血管闭塞后较不易梗死。 侧支供血使肺组织耐缺血。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-011":{"text":"快速上升使溶解于组织的氮气形成气泡，阻塞血流并刺激组织；关节肌肉痛和神经症状提示减压病。","references":[{"title":"Decompression Sickness - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537264/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-012":{"text":"长期未控高血压可使豆纹动脉破裂，引起壳核或基底节区脑出血，造成对侧肢体偏瘫。 壳核出血常由穿支小动脉病变所致。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-013":{"text":"左心室梗死后泵血下降，肺静脉和毛细血管静水压升高，液体进入肺泡，形成漏出性肺水肿。 肺泡积液通常是低蛋白漏出液。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-014":{"text":"长骨骨折后约一至三日出现突发呼吸困难，符合骨髓脂肪进入肺循环造成的脂肪栓塞综合征。 脂滴进入肺微循环会妨碍气体交换。","references":[{"title":"Chapter 10: Musculoskeletal System Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613072/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-015":{"text":"大块肺栓塞突然增加右心室后负荷，可致急性右心衰竭和心排量骤降，是猝死的主要机制。 肺血管阻力骤升可使右室扩张。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-016":{"text":"羊水栓塞可见胎儿鳞状细胞、胎毛和黏液进入肺血管；题库答案C仅称纤维蛋白血栓，不能代表特征性栓子，需复核。","references":[{"title":"Amniotic Fluid Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK559107/"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch02-en-single-017":{"text":"反常栓塞需静脉栓子经右向左分流进入体循环；单纯主动脉瓣狭窄不提供心内分流通道。 主动脉瓣狭窄不造成右向左分流。","references":[{"title":"Paradoxical Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470196/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-018":{"text":"房间隔缺损可在右心压力升高时出现右向左分流，使静脉栓子越过肺循环进入动脉系统。 栓子因此绕过肺部过滤床。","references":[{"title":"Paradoxical Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK470196/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-019":{"text":"减压病气泡主要由氮气析出形成；快速减压使原先溶于血液和组织的惰性气体形成气泡。 气泡增大并阻塞微循环。","references":[{"title":"Decompression Sickness - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537264/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-020":{"text":"骨折，尤其股骨等长骨骨折，可使骨髓脂肪进入血流，随后堵塞肺和其他器官微血管。 髓腔脂肪可经破损静脉进入循环。","references":[{"title":"Chapter 10: Musculoskeletal System Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613072/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-021":{"text":"下肢深静脉血流慢且易淤滞，卧床、手术和活动减少会进一步增加静脉血栓风险。 小腿和股静脉是常见血栓来源。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-022":{"text":"下肢动脉栓塞来自体循环左心，如左心房或左心室血栓；右心血栓通常进入肺动脉。 体静脉栓子不会直接进入主动脉。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-023":{"text":"颈静脉怒张、外周水肿和肝大提示静脉淤血；图中肝脏呈槟榔样改变，符合充血性心力衰竭。 慢性右心压力会损害肝小叶中心区。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-024":{"text":"上肢深静脉血栓经上腔静脉、右心进入肺循环，脱落后可阻塞肺动脉。 肺动脉是静脉血栓脱落后的首站。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-025":{"text":"大脑中动脉属于体循环，栓子通常来自左心；选项中左心室血栓可进入主动脉后栓塞脑动脉。 左心栓子可随主动脉血流进入颅内动脉。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-026":{"text":"肺栓子最常来自下肢近端深静脉血栓，随后经下腔静脉和右心到达肺动脉。 股静脉及髂静脉也常见血栓来源。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-027":{"text":"尸后凝血块呈鸡脂样或果冻样、不附着血管壁且缺乏层状结构；这些特征不支持生前血栓。 生前血栓通常附着于血管壁。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-028":{"text":"阿司匹林不可逆抑制血小板COX-1，减少血栓烷A2生成，主要抑制血小板聚集。 血小板不能重新合成被抑制的酶。","references":[{"title":"Platelets in the Pathogenesis of Vascular Disease and their Role as a Therapeutic Target","url":"https://www.ncbi.nlm.nih.gov/books/NBK534273/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-029":{"text":"胰腺癌可促发无菌性血栓性心内膜炎；瓣膜赘生物、血培养阴性及栓塞表现支持非细菌性赘生物。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-030":{"text":"冠状动脉粥样斑块破裂可损伤内皮并暴露促凝物质，激活血小板和凝血，形成急性冠脉血栓。 内皮损伤是Virchow三要素之一。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-031":{"text":"血管壁不附着、缺乏生前层状血栓结构支持尸后血凝块；题干称“深红实性”略不典型，但答案A为最合适选项。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-032":{"text":"心肌梗死、房颤、二尖瓣狭窄和扩张型心肌病可造成心腔内血流淤滞并形成附壁血栓；DIC以微血栓为主。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-033":{"text":"混合血栓含血小板、纤维蛋白和红细胞，常见于血流较慢或形成层次明显的血栓。 层状结构来自成分随血流交替沉积。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-034":{"text":"慢性肺淤血造成红细胞进入肺泡，随后被巨噬细胞吞噬并转为含铁血黄素细胞。 铁颗粒使这些巨噬细胞呈棕色。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-035":{"text":"转移癌、卧床、心肌梗死和因子V突变均明确促栓；某些白血病及治疗也会增加血栓风险，故“白血病不相关”过度概括，需复核。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch02-en-single-036":{"text":"细菌性心内膜炎赘生物由血小板、纤维蛋白、炎细胞及微生物构成，通常归为白色或血小板丰富的血栓。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-037":{"text":"DIC在小血管内广泛形成纤维蛋白微血栓，组织学常呈均质嗜酸性，称为透明血栓。 微血管受累可造成多器官缺血。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-038":{"text":"附壁血栓形成于心腔壁或大血管壁，含血小板、纤维蛋白和红细胞，属于混合血栓。 心腔内血流淤滞是形成背景。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-039":{"text":"透明血栓主要由纤维蛋白构成，常见于DIC等微循环血管；与含较多红细胞的静脉红色血栓不同。 这类血栓常见于小血管微循环。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-040":{"text":"硬膜下积液由创伤后出血在组织间隙内聚集形成，称血肿；瘀点和瘀斑描述皮肤或黏膜出血形态。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-041":{"text":"失血的后果取决于量、速度、部位及代偿能力。失血约20%已处于常用分级的第二级范围，不能保证不会出现循环灌注异常；E使用“可能”而非“必然”，将它直接判错缺少明确依据，本题待复核。","references":[{"title":"NCBI：失血与低血容量性休克","url":"https://www.ncbi.nlm.nih.gov/books/NBK513297/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch02-en-single-042":{"text":"左心室泵功能下降使肺静脉压和肺毛细血管静水压升高，推动液体进入肺间质和肺泡。 低射血分数也支持左心衰竭。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-043":{"text":"乳腺癌阻塞皮肤淋巴管，淋巴液潴留造成皮肤水肿、增厚和橘皮样改变。 这种皮肤改变也称橘皮征。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-044":{"text":"乳腺癌手术切除或损伤腋窝淋巴管后，淋巴回流受阻，患侧手臂可发生淋巴性水肿。 淋巴液和蛋白因而潴留于组织间隙。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-045":{"text":"慢性淤血导致实质细胞萎缩、间质增生、含铁血黄素沉积和血栓形成，不会促使实质细胞增殖。 慢性静脉压力损伤实质而非促其增殖。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-046":{"text":"紧张时交感反应使皮肤小动脉扩张、局部血流增加，属于主动性充血，而非静脉回流障碍。 面部泛红来自局部动脉血流增加。","references":[{"title":"Respiratory System, Mediastinum, and Pleurae","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7271179/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch02-en-single-047":{"text":"双下肢凹陷性水肿、颈静脉怒张和肝酶升高提示静脉压增高及肝淤血，常由充血性心力衰竭造成。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"},{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-048":{"text":"右心衰使体循环静脉压升高，易造成肝、脾和胃肠道淤血；肺淤血主要与左心衰有关。 这是全身静脉回流受阻的典型分布。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-049":{"text":"长期肝淤血可发生中心静脉周围纤维化，严重时发展为心源性肝硬化；因此“不会导致肝硬化”错误。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-050":{"text":"动脉性充血来自小动脉扩张，组织通常鲜红；蓝红色更符合静脉淤血造成的去氧血增多。 静脉血脱氧增加才会使组织发蓝。","references":[{"title":"Respiratory System, Mediastinum, and Pleurae","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7271179/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-051":{"text":"急性肺淤血时肺毛细血管压升高，血性漏出液进入肺泡；含铁巨噬细胞需要较长时间形成。 血性漏出液随后进入肺泡腔。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-052":{"text":"慢性二尖瓣狭窄会造成肺毛细血管淤血、肺泡出血和纤维化；透明膜更常见于弥漫性肺泡损伤，不是慢性淤血的典型表现。","references":[{"title":"Cardiac Cirrhosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK431053/"},{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch02-en-single-053":{"text":"图示冠状动脉腔内血栓和粥样硬化斑块可阻断心肌供血，导致缺血性心肌凝固性坏死。 缺血后细胞蛋白变性并暂时保留轮廓。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"},{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-054":{"text":"题干称胸痛仅45分钟后死亡，通常更符合早期心肌损伤；中性粒细胞浸润需更长时间，答案B的时间线索不吻合，需复核。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch02-en-single-055":{"text":"肺梗死位于胸膜下时可引发胸膜炎症和纤维素沉积，刺激胸膜痛觉神经产生胸痛。 胸膜受累时呼吸或咳嗽可加重疼痛。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-056":{"text":"左心衰是肺水肿最常见原因之一：左房和肺静脉压力升高，使肺毛细血管静水压上升。 肺静脉压升高是其直接生理基础。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-057":{"text":"住院卧床和活动受限使下肢静脉血流淤滞，符合Virchow三要素中的血流异常，易形成DVT并发生肺栓塞。 感染住院和活动减少进一步促进淤滞。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"},{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-058":{"text":"前列腺癌术后长时间制动可造成下肢静脉淤滞和深静脉血栓，血栓脱落后可能导致致命肺栓塞。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"},{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-059":{"text":"图示左心室壁明显增厚、心腔相对变小，符合长期压力负荷导致的向心性肥厚；常见病因是高血压。","references":[{"title":"Mechanisms and Morphology of Cellular Injury, Adaptation, and Death","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7171462/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-060":{"text":"骨盆及下肢骨折后两日出现呼吸急促和意识改变，符合脂肪栓塞综合征的肺部与神经表现。 脂肪栓堵塞肺微血管并可诱发炎症。","references":[{"title":"Chapter 10: Musculoskeletal System Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613072/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-061":{"text":"肺动脉栓塞造成胸膜下肺梗死时，因肺循环与支气管循环双重供血而常伴出血，肉眼呈红色楔形。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch02-en-single-062":{"text":"房颤和风湿性二尖瓣病导致左房扩张、血流淤滞及附壁血栓；脱落后进入体循环造成系统性栓塞。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-063":{"text":"肺栓塞可致猝死、肺梗死和慢性肺动脉高压；间质性肺炎并非其典型直接结局。 这些表现更符合反复或严重栓塞的后果。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-064":{"text":"肺血管有较大灌注储备，小栓子进入远端小动脉时常不造成明显临床后果；反复栓塞则可能升高肺压。","references":[{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-065":{"text":"长时间乘车使下肢静脉血流变慢，静脉淤滞促进血栓形成；腿部肿痛与股静脉血栓相符。 久坐或久卧都可触发静脉淤滞。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch02-en-single-066":{"text":"血栓机化后新生毛细血管贯穿并连接原有管腔，部分恢复血流，这一过程称为再通。 机化血栓可逐渐形成纤维性新管腔。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch02-en-single-067":{"text":"水肿来自静水压升高、胶体渗透压下降、通透性增加或淋巴回流受阻；单纯出血不是典型水肿机制。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-001":{"text":"结核分枝杆菌在巨噬细胞内存活并诱发肉芽肿；巨噬细胞活化后限制病原并组织后续免疫反应。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-002":{"text":"骨折后下肢肿痛提示深静脉血栓，卧床使血流淤滞；血栓脱落可经右心造成肺栓塞。 血栓并发症取决于位置和范围。","references":[{"title":"Thrombosis - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK538430/"},{"title":"Acute Pulmonary Embolism - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK560551/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-003":{"text":"二氧化硅被肺泡巨噬细胞吞噬后，巨噬细胞释放生长因子促成成纤维细胞增殖和胶原沉积。 这是尘肺纤维化的促纤维化反应。","references":[{"title":"Pathology, Inflammation - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK534820/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-004":{"text":"浅表烫伤造成血管通透性增加，浆液渗出并形成小水疱，属于浆液性炎症，而非脓性或肉芽肿性炎症。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-005":{"text":"发病数日并有发热、寒战和脓性咽部分泌物，符合以中性粒细胞为主的急性炎症。 脓液含中性粒细胞和坏死碎屑。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-006":{"text":"溃疡是上皮表面缺损并累及下方组织；十二指肠病灶伴隐血提示黏膜缺损，而非局限性脓肿。 溃疡边缘可伴慢性炎细胞浸润。","references":[{"title":"Pathology, Inflammation - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK534820/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-007":{"text":"缝线等异物难以被吞噬，周围巨噬细胞融合成多核巨细胞并形成肉芽肿，偏光材料支持缝线残留。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-008":{"text":"肉芽肿的核心是上皮样巨噬细胞聚集；坏死和Langhans巨细胞可出现，但不是各种肉芽肿都必有。 细胞呈上皮样外观，而非普通成纤维细胞。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-009":{"text":"慢性炎症常有淋巴细胞、巨噬细胞和浆细胞浸润，并持续数月或更久；其组织损伤常与修复并存。 组织损伤和修复可同时发生。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-010":{"text":"经典中性粒细胞趋化介质包括C5a、LTB4和趋化因子。原题却列C3a并笼统把前列腺素作为答案；不同前列腺素作用不同，不能不加限定地套用这一结论，需核对选项或原答案。","references":[{"title":"NCBI：急性炎症反应","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch03-en-single-011":{"text":"渗出液因炎症时血管通透性增加而含较多蛋白，通常比漏出液比重高；低蛋白液体更符合漏出液。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-012":{"text":"急性炎症时中性粒细胞通常最先大量迁出，之后单核细胞和巨噬细胞增多；它们由血管进入间质。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-013":{"text":"中性粒细胞吞噬细菌并释放氧化酶和蛋白酶，组织内寿命短；组胺主要由肥大细胞释放。 嗜碱性颗粒细胞才是组胺的主要来源。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-014":{"text":"双侧胸腔积液和全身凹陷性水肿提示血浆胶体渗透压下降；低白蛋白血症可同时解释这些表现。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-015":{"text":"肺炎球菌由中性粒细胞吞噬清除，呼吸爆发产生过氧化氢等活性氧，用于杀灭被吞噬细菌。 过氧化氢在吞噬体内参与杀菌。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-016":{"text":"结核肉芽肿中的抗原呈递细胞多由血液单核细胞进入组织后分化为巨噬细胞。 组织巨噬细胞可由循环单核细胞分化。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-017":{"text":"长时间乘机造成下肢静脉回流减慢，毛细血管静水压上升，液体滞留组织间隙导致鞋穿不回。 长途旅行后下肢可发生依赖性液体潴留。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-018":{"text":"胸腔液混浊且白细胞以中性粒细胞为主，符合脓性炎症；这比单纯浆液性积液含更多细胞和碎屑。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-019":{"text":"伤口形成坚硬、隆起的胶原性结节，符合瘢痕疙瘩；其胶原过度沉积可超出原有伤口范围。 过量胶原可使瘢痕超出原有创缘。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-020":{"text":"胎膜和绒毛膜中大量中性粒细胞提示上行性细菌感染；大肠杆菌是常见的羊膜腔感染病原。 感染还可引起早产和胎儿感染。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-021":{"text":"缝线能维持切口边缘接近，减少张力并支持一期愈合；感染、灌注差、低白蛋白和激素均会抑制修复。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-022":{"text":"败血症时巨噬细胞释放一氧化氮，引起广泛血管扩张和血压下降，进而导致休克及多器官灌注不足。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-023":{"text":"血管基底膜暴露的胶原可激活Hageman因子（因子XII），进而启动凝血和激肽系统。 因子XII可连接凝血与激肽两条级联反应。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-024":{"text":"皮肤伤口张力在最初数周快速上升，约三个月接近可达到的高值；重塑后仍难完全恢复正常强度。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-025":{"text":"酪氨酸激酶是细胞内信号酶，可传递生长因子刺激；层粘连蛋白、纤维连接蛋白和胶原属于细胞外基质。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-026":{"text":"表皮附属器中的毛囊和汗腺上皮可提供再生细胞；若附属器被深度破坏，烧伤区更可能靠瘢痕修复。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-027":{"text":"漏出液蛋白含量低、细胞少；本题选项中少量淋巴细胞最符合非炎症性液体，浑浊和纤维蛋白则提示渗出。","references":[{"title":"Physiology, Edema - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK537065/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-028":{"text":"成纤维细胞生长因子可促进内皮细胞增殖和新生毛细血管形成，参与肉芽组织血管化。 生长因子信号可促使内皮细胞形成管腔。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-029":{"text":"淋巴管将组织抗原和抗原呈递细胞带至淋巴结，使其接触淋巴细胞并启动特异性免疫。 树突细胞等抗原呈递细胞经淋巴迁移。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-030":{"text":"胃黏膜慢性单核细胞浸润和数周症状符合幽门螺杆菌相关慢性胃炎；辣椒刺激不会造成这种浸润模式。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-031":{"text":"C3b包被微生物后可被吞噬细胞的补体受体识别，增强结合与吞噬，这称为调理作用。应与C5a引导白细胞向炎症部位移动的趋化作用区分。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-032":{"text":"流感等病毒性肺炎主要累及肺间质，胸片可见双侧间质性浸润；局灶实变更偏细菌性肺炎。 病毒感染常累及肺泡间隔和肺间质。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-033":{"text":"蜂蜇后数分钟出现喘鸣、荨麻疹样红肿和水肿，符合IgE介导肥大细胞脱颗粒，组胺是关键介质。 血管扩张和通透性增高迅速造成水肿。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-034":{"text":"布洛芬抑制环氧化酶和前列腺素合成，减轻组织损伤后的疼痛；它不会直接促进纤溶或瘢痕形成。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-035":{"text":"反复季节性鼻炎提示花粉诱发的I型超敏反应，肥大细胞释放组胺引起鼻黏膜红肿、流涕和眼痒。 再次接触过敏原可迅速诱发肥大细胞脱颗粒。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-036":{"text":"新发压榨性胸痛且既往有心肌梗死，血清肌酸激酶升高可提示心肌细胞损伤；白细胞和血沉特异性较低。","references":[{"title":"Necrosis Pathology - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK557627/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-037":{"text":"硅胶属于难降解异物，持续刺激巨噬细胞融合成异物型多核巨细胞；急性中性粒细胞反应并非主型。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-038":{"text":"非干酪样肉芽肿中，T细胞分泌的IFN-γ可活化巨噬细胞并维持肉芽肿形成。 其作用不同于组胺引起的血管反应。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-039":{"text":"前列腺素可刺激子宫平滑肌收缩并促使宫颈成熟，因此用于药物诱导流产。 该机制模拟炎症介质的生理作用。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-040":{"text":"成熟骨骼肌纤维高度分化，通常不能像肝细胞、内皮或成纤维细胞那样重新进入增殖周期，故选B。肌肉损伤后仍可由卫星细胞参与有限修复，不能说骨骼肌完全没有再生能力。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-041":{"text":"胃窦黏膜表面上皮缺失形成局灶性缺损，且有呕血，符合消化性溃疡。 本题关键形态是上皮表面缺损。","references":[{"title":"Pathology, Inflammation - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK534820/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch03-en-single-042":{"text":"麻风分枝杆菌可诱发慢性肉芽肿性炎症，巨噬细胞上皮样转化、淋巴细胞浸润并逐渐纤维化。 慢性肉芽肿还可能造成神经和组织损害。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-043":{"text":"内皮E选择素与白细胞配体结合，促进滚动和黏附，是中性粒细胞从血管迁出的关键步骤。 E选择素是促进白细胞滚动的内皮黏附分子。","references":[{"title":"Leukocyte–Endothelial Cell Adhesion","url":"https://www.ncbi.nlm.nih.gov/books/NBK53380/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch03-en-single-044":{"text":"阿司匹林抑制环氧化酶，减少前列腺素生成；前列腺素介导血管扩张及痛觉敏化，因此疼痛暂时减轻。","references":[{"title":"Salicylic Acid (Aspirin) - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK519032/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-045":{"text":"肺叶内液化腔伴气液平面提示脓肿，即局灶性化脓性炎症和组织液化。 中心液化坏死和周围炎症共同形成脓腔。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch03-en-single-046":{"text":"缺血心肌修复时VEGF促进内皮增殖和新生血管形成；它支持损伤区恢复供血和愈合。 VEGF主要作用于血管内皮细胞。","references":[{"title":"Principles of Wound Healing","url":"https://www.ncbi.nlm.nih.gov/books/NBK534261/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch03-en-single-047":{"text":"C5a是强效趋化因子，可引导中性粒细胞从血流迁出并向淋球菌感染部位移动。 C5a还能促进白细胞活化。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch03-en-single-048":{"text":"急性阑尾炎中前列腺素增强痛觉敏化，缓激肽直接刺激痛觉神经，两者共同造成疼痛。 两种介质也解释炎症时的压痛和反跳痛。","references":[{"title":"Acute Inflammatory Response - StatPearls","url":"https://www.ncbi.nlm.nih.gov/books/NBK556083/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-001":{"text":"染料工业中的芳香胺是关键线索。这些物质经代谢后随尿液排出，使尿路上皮长期接触致癌物，因此与膀胱癌的联系最典型，选择E。","references":[{"title":"NCI：膀胱癌风险因素","url":"https://www.cancer.gov/types/bladder/hp/bladder-screening-pdq"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-002":{"text":"Burkitt淋巴瘤尤其是地方流行型与EB病毒密切相关，故选B。滤泡性淋巴瘤的经典机制则是BCL2相关染色体易位，不能把两种淋巴瘤混淆。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-003":{"text":"图中肝脏有许多散在、大小不一的结节，结合近期消瘦，更符合多发转移瘤。选项中B最合适；单凭肉眼图不能进一步确定原发器官，仍需组织学检查。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-004":{"text":"图示肿块呈不规则菜花状，题目意在考查恶性肿瘤在发现时可能已经发生转移，故原答案选C。肉眼外观不能证明它一定高分化或由特定病毒造成。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-005":{"text":"宫颈不规则肿块及经间期出血提示宫颈恶性肿瘤，高危型HPV是重要病因。原选项C把恶性肿瘤说成必然致死，表述过于绝对，不能据此判断个体预后；本题待复核。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch04-en-single-006":{"text":"便潜血阳性及图示结肠隆起性病变需要组织学判断。原选项B断言良性且不会复发，仅凭这张肉眼图无法支持；腺瘤也存在复发或再发可能，本题不宜按该断言判分。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch04-en-single-007":{"text":"移行细胞癌即尿路上皮癌，常呈乳头状向腔内生长，故选E。乳头状描述的是生长外形，不代表一定为良性，也不能单凭外形判断是否浸润。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-008":{"text":"基底细胞癌多发生于长期日晒部位，老年人的面部尤其鼻部是典型位置，故选B。手部也会日晒，但在所列部位中面部最符合常见分布。","references":[{"title":"NCI：皮肤癌","url":"https://www.cancer.gov/types/skin/hp/skin-treatment-pdq"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-009":{"text":"本题考查的是癌症死亡原因排序，不是所有疾病的死亡排序。按IARC的2022年中国数据，肺癌位于癌症死亡首位，故选C；统计结论应注明地区和年份。","references":[{"title":"IARC：2022年中国癌症统计","url":"https://gco.iarc.who.int/media/globocan/factsheets/populations/160-china-fact-sheet.pdf"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-010":{"text":"网状纤维染色可显示组织支架：癌通常表现为纤维围绕细胞巢，肉瘤常见纤维围绕个别瘤细胞，故传统鉴别题选E。实际诊断还需结合形态和免疫组化。","references":[{"title":"研究：网状纤维染色鉴别癌与肉瘤","url":"https://pubmed.ncbi.nlm.nih.gov/13536209/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-011":{"text":"胃癌突破浆膜后可在腹膜腔内种植，印戒细胞癌也可累及卵巢，故所列选项中B最典型。种植转移强调体腔内播散，与经血管或淋巴管转移不同。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-012":{"text":"肿瘤长得快并不意味着每个细胞的周期都更短。肿瘤细胞周期可与正常细胞相近甚至更长；参加增殖的比例和细胞丢失量也决定净增长，故选C。","references":[{"title":"NCBI：肿瘤增殖与生长比例","url":"https://www.ncbi.nlm.nih.gov/books/NBK13035/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-013":{"text":"β连环蛋白参与E钙黏蛋白的细胞黏附复合体，也参与WNT信号，故所列选项中A最相关。严格说，直接编码E钙黏蛋白的是CDH1，不能把两者当成同一个基因。","references":[{"title":"NCBI：癌细胞行为的分子基础","url":"https://www.ncbi.nlm.nih.gov/books/NBK26902/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-014":{"text":"EB病毒与鼻咽癌及部分淋巴瘤有关，故选D。宫颈癌主要关联高危型HPV，Kaposi肉瘤主要关联HHV-8；病毒与肿瘤的对应关系是本题重点。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-015":{"text":"不规则腺体、核深染及结肠溃疡性肿块支持腺癌。结直肠癌演进可出现TP53失活，选项中B最符合常见分子事件；题干没有足够证据直接诊断遗传性综合征。","references":[{"title":"NCBI：抑癌基因","url":"https://www.ncbi.nlm.nih.gov/books/NBK9894/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-016":{"text":"RAS结合GTP时处于活化状态，水解成GDP后关闭。若GTP水解功能丧失，促增殖信号持续存在，因此选C；其余选项不是这种GTP开关机制。","references":[{"title":"NCBI：癌细胞行为的分子基础","url":"https://www.ncbi.nlm.nih.gov/books/NBK26902/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-017":{"text":"子宫平滑肌瘤通常为良性，并非平滑肌肉瘤的常规前驱病变，故选D。宫颈异型增生、子宫内膜不典型增生及慢性炎症相关疾病则可增加相应癌症风险。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-018":{"text":"转移表示肿瘤细胞在与原发灶不连续的部位形成病灶，是判断恶性的明确依据，故选D。多形性、核分裂和坏死可提示恶性，但单独存在并非绝对证据。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-019":{"text":"小细胞肺癌患者出现高血压、面部改变和易瘀青，提示异位ACTH引起皮质醇增多，故选C。骨扫描无转移不排除这种由激素产生的副肿瘤效应。","references":[{"title":"NCBI：异位激素与副肿瘤综合征","url":"https://www.ncbi.nlm.nih.gov/books/NBK12609/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-020":{"text":"皮下、柔软、界限较清且多年无明显症状的肿块符合脂肪瘤，故选D。它由成熟脂肪细胞构成；快速增大、深部浸润等才需要警惕其他软组织肿瘤。","references":[{"title":"NCBI：脂肪瘤","url":"https://www.ncbi.nlm.nih.gov/books/NBK507906/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-021":{"text":"反应性淋巴细胞增生通常包含多个克隆，淋巴瘤则常由一个克隆扩增。抗原受体基因重排检测可提供克隆性证据，故选B；白细胞标志物阳性只能说明细胞来源。","references":[{"title":"NCBI：肿瘤发生与克隆性","url":"https://www.ncbi.nlm.nih.gov/books/NBK9963/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-022":{"text":"肝内多发结节伴中央脐凹提示转移瘤，意味着疾病已发生远处扩散，故D最合适。分期反映扩散范围，分级反映显微镜下分化程度，不能只凭转移判断高分级。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-023":{"text":"多年大小和颜色稳定的小红色皮肤结节，提示良性血管性病变，选A血管瘤。黑色素瘤常需警惕形态、色泽和大小变化；其余选项也不符合这种浅表血管样结节。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-024":{"text":"卵巢囊肿含毛发、皮脂，并有成熟皮肤、腺体和软骨，符合成熟性囊性畸胎瘤。其通常为良性，转移不常见，故选C；不能把成熟组织误认为未成熟胚胎成分。","references":[{"title":"NCBI：囊性畸胎瘤","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK564325/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-025":{"text":"HTLV-1可引起成人T细胞白血病/淋巴瘤，故选C。视网膜母细胞瘤主要涉及RB1失活，肝血管肉瘤的经典风险因素是特定化学物质暴露。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-026":{"text":"成人腹膜后巨大软组织肿块首先考虑该部位常见肉瘤，脂肪肉瘤符合其来源和位置，故选E。肿块巨大时才出现压迫性不适，也是深部软组织肿瘤的常见表现。","references":[{"title":"NCI：软组织肉瘤","url":"https://www.cancer.gov/types/soft-tissue-sarcoma/patient/adult-soft-tissue-treatment-pdq"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-027":{"text":"肿瘤发生具有年龄和部位分布特点，多数恶性肿瘤风险随年龄增加，某些肿瘤又可受激素影响。四项均是一般规律，故选E，但不能将年龄规律机械套用于每一种肿瘤。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-028":{"text":"副肿瘤综合征也可见于肉瘤，因此D明显错误。不过C称库欣综合征是最常见的内分泌表现也有疑点，高钙血症更常见。本题单选条件不严谨，保留原答案并待复核。","references":[{"title":"NCBI：副肿瘤综合征","url":"https://www.ncbi.nlm.nih.gov/books/NBK507890/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch04-en-single-029":{"text":"胚胎性抗原在成人并非只能由肿瘤表达，某些非肿瘤性状态也可升高，故C错误。CD20体现B细胞分化谱系，并不是只有恶性B细胞才表达的专属标志物。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-030":{"text":"原题可能想考HTLV-1作为直接致瘤的RNA逆转录病毒，故给D。但HCV也是RNA病毒且具有致癌性；若题干只说致癌RNA病毒，B也符合，需补充限定条件后再判分。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch04-en-single-031":{"text":"经典化学致癌模型中，启动造成较持久的遗传改变，促进则推动已启动细胞增殖，其作用可逆且通常需持续刺激，故选B。启动剂不一定都能直接作用，有些需代谢活化。","references":[{"title":"NCBI：肿瘤发生与克隆性","url":"https://www.ncbi.nlm.nih.gov/books/NBK9963/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-032":{"text":"肿瘤血管生成取决于促血管与抑血管因子的相对作用，两类因子可同时存在，故E正确。VEGF可由肿瘤和间质细胞产生，肿瘤血管也常与正常血管不同。","references":[{"title":"NCI：肿瘤血管生成","url":"https://www.cancer.gov/about-cancer/treatment/types/immunotherapy/angiogenesis-inhibitors-fact-sheet"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-033":{"text":"WT1、VHL和RB都可涉及抑癌基因功能丧失，原题据此选C。不过A对抑癌基因作用的概括也不宜直接判错；且这些基因具体生理功能不同，本题措辞需复核。","references":[{"title":"NCBI：抑癌基因","url":"https://www.ncbi.nlm.nih.gov/books/NBK9894/"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch04-en-single-034":{"text":"Li-Fraumeni综合征的典型基础是胚系TP53异常，主要影响细胞周期检查和凋亡，不属于经典DNA修复酶缺陷综合征，故选D。其余疾病分别涉及不同的修复或基因组稳定机制。","references":[{"title":"NCBI：抑癌基因与遗传性肿瘤","url":"https://www.ncbi.nlm.nih.gov/books/NBK532243/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-035":{"text":"一般而言，生长较快、侵袭性较强的肿瘤转移风险较高，B是趋势性表述。区域淋巴结肿大也可能是反应性增生；肉瘤并非绝对只能经血道转移。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-036":{"text":"本题按传统肿瘤干细胞模型选B：其中部分细胞处于慢周期或静息状态，可能逃避针对增殖细胞的治疗。但这是部分群体的特点，不能理解为所有肿瘤干细胞都分裂缓慢。","references":[{"title":"NCBI：肿瘤增殖与生长比例","url":"https://www.ncbi.nlm.nih.gov/books/NBK13035/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-037":{"text":"错构瘤由该部位本来就存在的成熟组织构成，但比例和排列异常，故选C。畸胎瘤可出现来源于不同胚层的组织，而瘢痕疙瘩属于异常修复，并非同一概念。","references":[{"title":"NCBI：错构瘤","url":"https://www.ncbi.nlm.nih.gov/books/NBK562298/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-038":{"text":"肿瘤的实质是肿瘤细胞本身，决定组织来源、主要形态和命名，故选A。间质提供血管及支持结构，对生长重要，但不是区分肿瘤类型的首要依据。","references":[{"title":"SEER：肿瘤分类","url":"https://training.seer.cancer.gov/disease/categories/classification.html"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-039":{"text":"浸润说明肿瘤突破正常组织界限向周围生长，是此题最有力的恶性依据，故选D。核质比增大、异型性和坏死需结合整体结构判断，单项不能替代浸润证据。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-040":{"text":"肺内多发结节提示远处转移，符合M1。原答案E还要求T4和区域淋巴结N1，但题干写右乳肿块、左腋窝结节，侧别不符；固定也不等于已经证实胸壁浸润，本题待复核。","references":[{"title":"NCI：乳腺癌TNM分期","url":"https://www.cancer.gov/types/breast/stages/tnm-staging-system"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch04-en-single-041":{"text":"原位癌的要点是异常上皮细胞尚未突破基底膜。黏膜内癌可已进入黏膜固有层，不能在所有器官中与原位癌等同，故C不准确；具体分期还需按器官标准区分。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-042":{"text":"失分化指肿瘤细胞失去正常组织的形态和功能特点，是恶性转化的重要表现，故选B。单有巨细胞或核分裂不等于恶性，肿瘤大小也不直接决定组织学分级。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-043":{"text":"原题按传统癌前病变列表选D：甲状腺腺瘤本身不等同于癌前病变。应注意乳头状瘤的风险取决于部位、病理分型和是否存在异型增生，不能笼统断言所有此类病变都会癌变。","references":[{"title":"Rubin病理学：肿瘤章节","url":"https://downloads.lww.com/wolterskluwer_vitalstream_com/sample-content/9780781795166_Rubin/samples/91731_ch06.pdf"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-044":{"text":"骨瘤是形成成熟骨组织的良性肿瘤，故选C。精原细胞瘤、肾母细胞瘤和白血病均为恶性疾病；英语名称以-oma结尾并不能保证其良性。","references":[{"title":"SEER：肿瘤分类","url":"https://training.seer.cancer.gov/disease/categories/classification.html"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-045":{"text":"交界性肿瘤指生物学行为处于良性与恶性之间的一类病变，故选D。它不是癌与肉瘤混合，也不是两种上皮癌混合；具体诊断标准取决于器官和肿瘤类型。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-046":{"text":"晚期播散性肿瘤可通过炎症介质和代谢异常造成消瘦、肌肉丢失及乏力，即恶病质，故选A。黄疸等表现依赖具体受累器官；题干的生存率不能推广到所有癌种。","references":[{"title":"NCBI：副肿瘤综合征","url":"https://www.ncbi.nlm.nih.gov/books/NBK507890/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-047":{"text":"紫外线可造成皮肤细胞DNA损伤，是日晒部位黑色素瘤的重要风险因素，因此选D。若明确指手掌或甲下的肢端型黑色素瘤，其风险特点不同，不能直接套用日晒结论。","references":[{"title":"NCI：皮肤癌与紫外线","url":"https://www.cancer.gov/types/skin/hp/skin-prevention-pdq"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-048":{"text":"血管生成是新生血管长入并为肿瘤提供营养的过程，故选C。肿瘤细胞进入血管是血管侵犯，沿血流播散是血行转移，与形成新血管不是同一概念。","references":[{"title":"NCI：肿瘤血管生成","url":"https://www.cancer.gov/about-cancer/treatment/types/immunotherapy/angiogenesis-inhibitors-fact-sheet"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-049":{"text":"术中冰冻切片能较快判断送检切缘是否有肿瘤，帮助决定切除范围，故选C。血清肿瘤标志物不能定位切缘，最终判断仍需结合充分取材后的常规病理。","references":[{"title":"SEER：病理检查与切缘","url":"https://training.seer.cancer.gov/staging/sources/pathologic.html"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-050":{"text":"氯乙烯是肝血管肉瘤的经典职业暴露因素，原题选E；但砷也属于已知风险因素，A同样有依据。这道单选题存在多个成立选项，不能强行只认E。","references":[{"title":"NCBI：肝血管肉瘤","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK538224/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch04-en-single-051":{"text":"BRCA1参与DNA损伤修复，其胚系致病变异可增加遗传性乳腺癌风险，故选B。ERBB2扩增多为肿瘤细胞的体细胞变化，不能与家族遗传易感混为一谈。","references":[{"title":"NCI：BRCA基因与遗传性肿瘤","url":"https://www.cancer.gov/about-cancer/causes-prevention/genetics/brca-fact-sheet"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-052":{"text":"结肠腺瘤到浸润癌通常是多步骤演进，逐渐积累促生长基因及抑癌基因改变，故选C。题干限定散发性病变，不应直接用遗传性修复缺陷解释全部病例。","references":[{"title":"NCBI：抑癌基因","url":"https://www.ncbi.nlm.nih.gov/books/NBK9894/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-053":{"text":"高生长比例表示较多肿瘤细胞处于增殖周期，传统细胞毒化疗常对这些细胞更敏感，故选A。药物种类、耐药机制和组织分布同样重要，不能据此预测所有治疗反应。","references":[{"title":"NCBI：肿瘤增殖与生长比例","url":"https://www.ncbi.nlm.nih.gov/books/NBK13035/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-054":{"text":"儿童反复出现皮肤癌提示着色性干皮病等DNA修复异常。核苷酸切除修复失败，使紫外线造成的DNA损伤积累，故选D；父母不患病并不排除隐性遗传病。","references":[{"title":"GeneReviews：着色性干皮病","url":"https://www.ncbi.nlm.nih.gov/books/NBK1397/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-055":{"text":"肝内黏液分泌性腺癌首先考虑转移性腺癌。所列部位中结肠最符合其腺体来源及经门静脉入肝的途径，故选D；实际确定原发灶仍需免疫组化和临床检查。","references":[{"title":"NCI：癌症的性质与分类","url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-056":{"text":"ERBB2即HER2，其扩增可增强生长信号，与部分乳腺癌较强的侵袭性有关，故选B。分化较好不保证不会迅速转移；但病程本身不能替代HER2检测结果。","references":[{"title":"NCI：乳腺癌诊断与分子检测","url":"https://www.cancer.gov/types/breast/diagnosis"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-057":{"text":"研究中可利用X染色体失活模式判断细胞是否来自同一克隆，故选E。角蛋白只能说明上皮来源，Ki-67或S期比例反映增殖，不能单独证明是真性肿瘤而非增生。","references":[{"title":"NIH：肿瘤与X染色体失活","url":"https://www.ncbi.nlm.nih.gov/books/NBK20362/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-058":{"text":"高危型HPV的E7蛋白可使RB蛋白失去抑制细胞周期的作用，故选D；E6主要促进p53降解。两种病毒蛋白靶点不同，应分别记忆。","references":[{"title":"NCBI：抑癌基因","url":"https://www.ncbi.nlm.nih.gov/books/NBK9894/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-059":{"text":"肿瘤细胞需与基底膜和细胞外基质结合并穿过它们，才能完成浸润。层粘连蛋白相关受体增加可促进这种相互作用，因此A比角蛋白表达或克隆性更直接关联转移过程。","references":[{"title":"NCBI：癌细胞行为的分子基础","url":"https://www.ncbi.nlm.nih.gov/books/NBK26902/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-060":{"text":"慢性肝炎造成持续损伤、炎症和反复再生，增加遗传改变积累的机会，故选C。HBV和HCV机制并不完全相同，尤其不能说二者都通过相同方式整合宿主基因组。","references":[{"title":"NCI：感染因素与癌症","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/infectious-agents"}],"status":"explained","originalAnswer":["C"]},"pathology-ch04-en-single-061":{"text":"原题把胃癌列为饮酒不增加风险的例外，给D。但现有资料也将大量饮酒列为胃癌风险因素，旧题的绝对表述不宜继续使用；此题保留原答案并标为待复核。","references":[{"title":"American Cancer Society：饮酒与癌症风险","url":"https://www.cancer.org/cancer/risk-prevention/diet-physical-activity/alcohol-use-and-cancer.html"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch04-en-single-062":{"text":"肾细胞癌容易侵犯肾静脉，并可沿下腔静脉延伸或经血流转移，故选B。多数癌常见淋巴道播散，但不能因此排除某些癌显著的血行扩散倾向。","references":[{"title":"SEER：肾癌扩散途径","url":"https://training.seer.cancer.gov/kidney/abstract-code-stage/extent/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-063":{"text":"宫颈细胞学筛查能在浸润癌出现前发现部分高级别病变，配合后续诊治降低死亡，故选D。现代筛查还常采用高危型HPV检测，这与本题所考历史贡献并不冲突。","references":[{"title":"NCI：宫颈癌筛查","url":"https://www.cancer.gov/types/cervical/hp/cervical-screening-pdq"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-064":{"text":"肿瘤体积倍增取决于产生多少新细胞以及丢失多少细胞，故A抓住生长比例和细胞丢失率。它不等同于单个细胞走完一个周期的时间，后者只是影响因素之一。","references":[{"title":"NCBI：肿瘤增殖与生长比例","url":"https://www.ncbi.nlm.nih.gov/books/NBK13035/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-065":{"text":"纤维肉瘤和脂肪肉瘤属于间叶来源，但精原细胞瘤属于生殖细胞肿瘤，不能把所有选项都归为间叶性。原答案E不成立，且C和D均符合，需复核题型或选项。","references":[{"title":"SEER：肿瘤分类","url":"https://training.seer.cancer.gov/disease/categories/classification.html"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch04-en-single-066":{"text":"题干列出的相关基因参与DNA错配修复，修复失效可导致复制错误积累和微卫星不稳定，故选D。其机制不同于家族性腺瘤性息肉病的APC/WNT通路异常。","references":[{"title":"NCI：遗传性结直肠癌","url":"https://www.cancer.gov/types/colorectal/hp/colorectal-genetics-pdq"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-067":{"text":"年轻女性乳房出现边界清楚、韧而可活动的肿块，典型考虑纤维腺瘤，故选A。皮肤正常、无腋窝结节支持局限性病变，但临床仍需影像和必要的病理确认。","references":[{"title":"NCBI：乳腺纤维腺瘤","url":"https://www.ncbi.nlm.nih.gov/books/NBK535345/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-068":{"text":"肿瘤大小、分化、切缘及原发或转移属性都会直接影响分期、治疗和预后，故传统题目选D。炎症量不是这里最主要的指标，但不能理解为肿瘤免疫微环境毫无意义。","references":[{"title":"NCI：肿瘤分级与分期","url":"https://www.cancer.gov/about-cancer/diagnosis-staging/diagnosis/tumor-grade"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-069":{"text":"老年前列腺硬结伴PSA明显升高，应高度怀疑前列腺腺癌，故选B。PSA并非癌症特异指标，炎症等也可升高，最后仍需以组织学诊断确认。","references":[{"title":"NCI：前列腺癌与PSA筛查","url":"https://www.cancer.gov/types/prostate/patient/prostate-screening-pdq"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-070":{"text":"左锁骨上淋巴结可接受经胸导管上行的腹腔淋巴，引流范围内的癌可在此转移。所列选项中结肠腺癌最符合；肉瘤较常血行转移，不能仅按肿块邻近肩部推断来源。","references":[{"title":"NCBI：左锁骨上淋巴结","url":"https://www.ncbi.nlm.nih.gov/books/NBK556100/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch04-en-single-071":{"text":"先遗传一个失活等位基因，后在体细胞中丢失另一个正常拷贝，是RB1相关视网膜母细胞瘤的两次打击模型，故选D。RB功能丧失使G1到S期的调控失效。","references":[{"title":"NCBI：抑癌基因","url":"https://www.ncbi.nlm.nih.gov/books/NBK9894/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch04-en-single-072":{"text":"家族史加数百个结肠腺瘤提示家族性腺瘤性息肉病。早期APC失活使β连环蛋白难以被降解，WNT信号持续活化，故选A；TP53异常一般位于较晚环节。","references":[{"title":"NCBI：癌细胞行为的分子基础","url":"https://www.ncbi.nlm.nih.gov/books/NBK26902/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch04-en-single-073":{"text":"多位近亲在年轻时发生不同类型恶性肿瘤，尤其肉瘤和白血病，提示Li-Fraumeni综合征，相关基因为TP53，故选E。吸烟解释个体风险，但不能解释这种家族聚集模式。","references":[{"title":"NCBI：抑癌基因与遗传性肿瘤","url":"https://www.ncbi.nlm.nih.gov/books/NBK532243/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch04-en-single-074":{"text":"BCL2过度表达可抑制细胞凋亡，使本应被清除的淋巴细胞积累，故机制选D。题干写细胞核染色不典型，常规BCL2免疫染色主要呈胞质分布，不能把该定位描述照搬为知识点。","references":[{"title":"NCBI：癌细胞行为的分子基础","url":"https://www.ncbi.nlm.nih.gov/books/NBK26902/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-001":{"text":"既往风湿性瓣膜损伤形成异常瓣膜表面，易被菌血症中的草绿色链球菌定植；发热、脾区疼痛提示感染性心内膜炎并脾栓塞，Roth斑也支持栓塞性表现。A组链球菌引发风湿热，不是此次心内膜感染的常见病原。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-002":{"text":"咽炎后关节痛、抗链球菌溶血素O升高及心脏炎指向急性风湿热。心肌间质的纤维素样坏死周围出现Anitschkow细胞构成Aschoff小体，是风湿性心肌炎的典型病灶；脆弱赘生物更符合感染性心内膜炎。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-003":{"text":"风湿热后出现舒张期开瓣音和隆隆样舒张期杂音，提示二尖瓣口狭窄。瓣口受限使左房排血受阻，常引起肺淤血和呼吸困难；主动脉瓣病变通常表现为主动脉区杂音或脉压改变。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-004":{"text":"劳力性心绞痛、晕厥、左心衰，加上收缩期左室与主动脉间明显压差，说明主动脉瓣狭窄。按本题传统病理学设定，最常见病因选风湿性瓣膜病；老年退行性钙化也是现实中常见原因，题目未列出。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-005":{"text":"水冲脉提示收缩压升高且舒张压下降，结合舒张期杂音，符合主动脉瓣关闭不全。舒张期血液返流入左室造成脉压增宽；二尖瓣反流主要产生收缩期杂音。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-006":{"text":"劳力性胸痛、晕厥、心衰和喷射性收缩期杂音组成主动脉瓣狭窄的典型表现。长期压力负荷导致左室向心性肥厚；主动脉瓣关闭不全则以舒张期杂音和水冲脉为线索。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-007":{"text":"左室壁增厚、腔变小及肌细胞矩形核是压力负荷所致向心性肥大，右室正常且瓣膜无病变，最支持长期体循环高血压。容量负荷通常使心腔扩张，肺源性心脏病主要累及右室。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-008":{"text":"心梗数日后新出现全收缩期杂音，提示乳头肌缺血坏死并断裂，造成急性二尖瓣反流；左房压力在收缩晚期升高也符合反流血流进入左房。室壁破裂通常导致心包填塞和猝死。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-009":{"text":"心肌梗死最早期的光镜改变为缺血区心肌纤维波浪状排列，反映周围存活肌纤维被牵拉。细胞核溶解和中性粒细胞浸润需更晚出现；心肌以凝固性坏死为主，并非液化性坏死。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-010":{"text":"透壁性梗死可累及心外膜，数日内引起邻近心包的急性纤维素性炎症，因此较早出现浆液纤维素性心包炎。心脏破裂及室壁瘤通常在随后数日到数周发生，附壁血栓可更早形成但本题强调特征性并发症。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-011":{"text":"梗死后先发生线粒体肿胀等不可逆细胞损伤，随后中性粒细胞先于巨噬细胞进入清除坏死组织；肉芽组织形成后，胶原逐渐沉积成为瘢痕。答案序列符合由细胞损伤到炎症清除再修复的时间进程。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-012":{"text":"持续胸痛、ST段抬高和病理性Q波提示急性透壁性心梗；前壁左室对应左冠状动脉前降支供血区，最常由斑块破裂后血栓完全阻塞造成。单纯多支狭窄可致缺血，但不能最好解释急性梗死。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-013":{"text":"胸痛由劳力诱发且近期变得更频繁、更久并不能休息缓解，说明稳定型心绞痛已转为不稳定型。常见机制是原有冠脉粥样斑块破裂或糜烂并形成非完全闭塞血栓；若已坏死才会有心肌损伤标志物升高。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-014":{"text":"运动诱发胸痛，休息或硝酸甘油后数分钟缓解，症状模式长期稳定且心电图无特异变化，符合稳定型心绞痛。心肌缺血是可逆的，心肌梗死则疼痛持续且伴坏死标志物升高。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-015":{"text":"颈静脉怒张、肺部湿啰音、外周水肿和肝大显示左右心衰及静脉淤血。长期高血压增加左室后负荷，促使心肌肥厚并最终收缩功能下降，造成心排出量不足和肺、体循环淤血。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-016":{"text":"肝脏呈红褐色背景夹杂黄色斑驳区，是慢性被动淤血形成的“槟榔肝”。右心衰使肝静脉压升高，中心静脉周围淤血和缺氧，故最符合右心衰竭。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-017":{"text":"肾动脉以下腹主动脉出现搏动性扩张，是典型腹主动脉瘤部位；动脉粥样硬化可损伤中膜并削弱管壁，常导致这种动脉瘤。高血压会增加壁应力，但不是该部位最典型的基础病因。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-018":{"text":"长期高血压合并糖尿病及肾功能减退，入球小动脉壁均匀、玻璃样嗜酸性物质沉积，符合玻璃样小动脉硬化。纤维素样坏死和洋葱皮样增生见于恶性高血压相关血管损伤。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-019":{"text":"小血管壁均匀粉红色玻璃样沉积、管腔变窄，是玻璃样小动脉硬化的形态特征，常见于良性高血压和糖尿病。洋葱皮样同心性增厚则提示增生性小动脉硬化。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-020":{"text":"糖尿病性胰岛素不足或抵抗会增加肝脏合成并减少清除富含甘油三酯的极低密度脂蛋白，造成常见的继发性高甘油三酯血症。高密度脂蛋白通常降低，不能解释题干所述甘油三酯升高。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-021":{"text":"冠状动脉狭窄已达显著程度，题目所列危险因素中糖尿病是明确的动脉粥样硬化风险因素。体重指数约30.5也提示肥胖，但原题标准答案指向糖尿病；职业和性格特征不是主要确定性危险因素。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-022":{"text":"血压短期骤升至250/125 mmHg并伴肌酐快速升高，符合恶性高血压造成的急性小血管损伤。入球小动脉可出现纤维素样坏死；玻璃样变多见于长期、较缓慢的良性高血压。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-023":{"text":"肾小动脉壁均质嗜酸性玻璃样物质使管腔狭窄，结合长期高血压和肾衰，符合良性高血压性肾硬化。恶性高血压则多见纤维素样坏死和点状出血。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-024":{"text":"冠脉横切面可见粥样斑块及复杂脂质核心，典型成熟斑块由泡沫细胞、坏死区、胆固醇裂隙和钙化构成。单纯泡沫细胞或平滑肌帽描述的是较早病变。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-025":{"text":"主动脉内膜线状脂纹在儿童即可出现，主要由内膜内脂质充盈的泡沫细胞构成，并有T淋巴细胞参与；尚未形成成熟斑块的坏死核心和纤维帽。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-026":{"text":"吸烟、高血压和高胆固醇通过损伤或激活内皮，引起通透性增加、白细胞黏附及血小板和凝血反应，推动动脉粥样硬化。LDL氧化被抑制会减轻而非促进斑块形成。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-027":{"text":"动脉粥样硬化起始环节是内皮细胞功能损伤或激活，导致脂蛋白进入内膜、白细胞黏附并招募单核细胞。平滑肌迁移和泡沫细胞积聚属于后续过程。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-028":{"text":"斑块破裂、表面溃疡、血栓及斑块内出血均可引发急性冠脉事件；中膜变薄不是斑块不稳定和急性死亡的主要相关变化。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-029":{"text":"原有冠脉狭窄患者近期症状加重，最能解释病情恶化的是斑块纤维帽破裂或裂隙形成并叠加部分血栓，导致管腔进一步狭窄及急性缺血。单纯血压升高或心肌肥厚不能解释新发不稳定症状。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-030":{"text":"双心室扩张、心律失常，活检见心肌细胞坏死伴淋巴细胞浸润，提示病毒性心肌炎。肠道病毒科柯萨奇病毒是经典病原；链球菌或葡萄球菌通常不会呈现这种典型淋巴细胞性心肌炎图景。题中A选项型别需留意版本差异。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-031":{"text":"肝大压痛、下肢水肿、胸腔积液和过度充气肺提示慢性肺病导致肺动脉高压及右心衰竭（肺心病）。慢阻肺可造成低氧性肺血管收缩和右室负荷增加；单纯体循环高血压主要引起左心改变。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-032":{"text":"咽炎后数周出现舞蹈症、游走性关节痛、皮下结节和心包摩擦音，符合急性风湿热。抗链球菌溶血素O升高可证明近期A组链球菌感染；CK-MB升高指向心肌坏死而非免疫后遗症。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-033":{"text":"冠脉横切面显示粥样斑块表面血栓，提示急性冠脉阻塞。糖尿病会加速冠状动脉粥样硬化，是年轻女性发生致命冠脉事件的重要危险因素。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-034":{"text":"打开的心包腔内充满大量血液和凝块，提示心肌游离壁破裂导致心包填塞。结合此前胸痛病程，最符合透壁性心肌梗死后机械性破裂。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-035":{"text":"近期感染后出现Aschoff小体和Anitschkow细胞、瓣膜闭合线小赘生物，确诊急性风湿性心脏炎。愈合过程中瓣叶增厚、交界融合和腱索缩短可造成慢性二尖瓣狭窄并常伴关闭不全。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-036":{"text":"四腔扩张、射血分数下降至30%、多瓣反流且冠脉基本正常，符合扩张型心肌病。心室扩张使瓣环扩大并引发功能性二尖瓣、三尖瓣反流；限制型心肌病以舒张充盈受限为主。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-037":{"text":"年轻患者突然晕厥且CK-MB升高，题目选项中家族性高胆固醇血症会导致早发冠状动脉粥样硬化和心肌缺血。仅给出的检查缺少家族史或血脂证据，不能排除其他急性心肌病因，需谨慎理解标准答案。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-038":{"text":"既往有显著冠脉狭窄，现发生心脏骤停，提示可能出现急性心肌梗死。CK-MB是心肌损伤后升高的血清标志物；抗DNA抗体、ANCA和抗链球菌抗体分别指向其他免疫或感染性疾病。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-039":{"text":"心肌切片可见梗死区域心肌纤维损伤及炎症细胞反应，符合心肌梗死后的组织学改变。病毒性心肌炎通常以弥漫或灶性淋巴细胞浸润伴肌细胞损伤为主。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-040":{"text":"胸痛发作约数小时后到院，心肌坏死标志物已可能开始升高。题目所列检测中CK-MB较适于提示心肌损伤；脂肪酶和转氨酶缺乏心脏特异性。临床诊断当前通常还会优先检测肌钙蛋白。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-041":{"text":"儿童左室及室间隔显著肥厚、收缩期二尖瓣前叶向流出道移动、射血分数高但腔小，符合肥厚型梗阻性心肌病。肌节蛋白基因（包括β肌球蛋白重链）突变是常见遗传机制；炎症或风湿证据不符。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-042":{"text":"大体图显示瓣膜上有不规则、易碎赘生物，结合甲下出血提示感染性栓塞，符合急性感染性心内膜炎。风湿性赘生物通常较小且沿瓣膜闭合线排列。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch05-en-single-043":{"text":"图中左室游离壁形成薄壁瘤样膨出，是梗死后室壁瘤的表现。室壁运动异常及心腔内淤滞易形成附壁血栓，脱落后可造成体循环血栓栓塞。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-044":{"text":"青少年运动后猝死并有劳力性胸痛，提示肥厚型心肌病。典型病理为肥厚的室间隔肌细胞排列紊乱并伴间质纤维化，可导致流出道梗阻和恶性心律失常；瓣膜感染或慢性风湿病不合年龄与线索。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-045":{"text":"长期呼吸困难、肺水肿和明显左室肥厚体现长期压力负荷导致的左心衰。体循环高血压可使左室向心性肥厚，随后舒张与收缩功能受损；三尖瓣反流主要导致右心容量负荷。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch05-en-single-046":{"text":"双心室收缩减弱、心腔扩大、射血分数下降并出现系统性栓塞，最符合扩张型心肌病。心腔扩张和低流速促成附壁血栓，脱落后可栓塞脑、肾、脾及肢体动脉。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-047":{"text":"急性冠脉血栓可造成透壁梗死，后续并发症包括心室破裂、附壁血栓及全身栓塞、室壁瘤和心包炎，故所列均可能。实际发生与梗死范围、部位和治疗有关，并非每位患者都会出现全部并发症。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch05-en-single-048":{"text":"持续低热、脾大压痛、掌跖痛性出血结节及心杂音指向感染性心内膜炎并出现栓塞/免疫现象。草绿色链球菌常在受损瓣膜上引起亚急性感染；柯萨奇病毒则常引起心肌炎而非赘生物。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch05-en-single-049":{"text":"链球菌咽炎后出现风湿性心脏炎，短期内左心衰及房颤最可能由心肌炎导致的心肌收缩损害引起。瓣膜纤维化和交界融合属于多年后形成的慢性后遗症，不会在住院数日内出现。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"},{"title":"Acute Rheumatic Fever and Rheumatic Heart Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK606315/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch05-en-single-050":{"text":"劳力时胸痛且硝酸甘油缓解，符合稳定型心绞痛，其最常见结构基础是冠状动脉粥样硬化导致固定性狭窄。心脏大小正常、无杂音并不排除冠脉病变；心包填塞会产生低血压和静脉淤血表现。","references":[{"title":"Chapter 5 Cardiovascular Alterations","url":"https://www.ncbi.nlm.nih.gov/books/NBK613064/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-001":{"text":"眼球内陷、瞳孔缩小、眼睑下垂和无汗构成Horner综合征，合并肺尖肿块及第一肋骨破坏提示肺尖癌侵犯交感神经链和胸壁。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-002":{"text":"肠结核常累及回盲部，因为该处内容物停留较久、淋巴组织丰富；空肠和十二指肠不是最常见部位。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-003":{"text":"继发性肺结核主要经支气管播散，淋巴或血行播散不是其主要途径；好发肺尖并常有新旧病灶并存及空洞形成。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-004":{"text":"继发性结核常由内源性再燃引起，上肺野病变较重，新旧病灶并存；肺门淋巴结显著病变更常见于原发结核。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-005":{"text":"慢性纤维空洞型结核的空洞壁常有干酪样坏死，含大量结核分枝杆菌，且常与支气管相通，利于排菌和传播。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-006":{"text":"结核浸润灶肺泡内以浆液、单核细胞和淋巴细胞为主；大量中性粒细胞更提示化脓性细菌感染，不是典型结核浸润。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-007":{"text":"结核球是肺内单个、界限相对清楚的干酪样坏死灶，可有纤维包膜；它是肿瘤样病灶，并非真正良性或恶性肿瘤。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-008":{"text":"成人继发性肺结核最常见的临床病理类型为浸润型，常位于肺上叶并可出现干酪坏死或空洞。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-009":{"text":"继发结核多因内源性再燃，病灶常位于肺尖且新旧并存，主要沿支气管播散；淋巴和血行播散并非主要方式。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-010":{"text":"结核属于迟发型细胞免疫反应，而非免疫复合物介导的III型变态反应。钙化坏死灶仍可能存留休眠菌，空洞型病灶有传染性。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-011":{"text":"原发结核灶可经血行播散，形成急性粟粒性结核；浸润型、干酪性肺炎和慢性空洞型多属继发性结核表现。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-012":{"text":"原发肺结核的原发灶多位于肺中下部胸膜下，典型区域是上叶下部或下叶上部；肺尖则是继发结核常见部位。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-013":{"text":"男性生殖系统结核最常累及附睾，感染可沿输精管向前列腺或精囊扩展，也可造成附睾结节和不育。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-014":{"text":"肠结核溃疡沿肠管长轴排列，常见于回盲部；溃疡边缘可不整，慢性炎症也可能造成狭窄或瘘管。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-015":{"text":"脊柱结核常累及胸腰段而非以上胸椎为主，也可累及长骨和指骨，并形成干酪坏死、死骨或寒性脓肿。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-016":{"text":"结核性脑膜炎多由血行播散，常累及脑底并见胶冻样渗出，儿童较多；典型渗出并非大量纤维脓性物。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-017":{"text":"肠结核多累及回盲部，溃疡通常横向排列；结核感染可累及肠道，但“可呈原发结核”是本题可成立的描述。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-018":{"text":"女性生殖系统结核最常累及输卵管，常为双侧，继而蔓延到子宫内膜或卵巢，可导致不孕。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-019":{"text":"小细胞肺癌具有神经内分泌分化，可异位分泌激素并引起副肿瘤综合征；它与吸烟密切相关，且恶性度高。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-020":{"text":"小细胞肺癌通常位于肺门附近的中央型肿块，与吸烟高度相关，常见神经内分泌颗粒，治疗以全身化疗和放疗为主。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-021":{"text":"肺鳞癌多见于吸烟者，通常为中央型并起自支气管上皮鳞状化生；异位激素分泌更典型于小细胞癌。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-022":{"text":"支气管类癌通常生长较慢、恶性程度低于小细胞癌及常见非小细胞癌；少数仍可转移，不能视为绝对良性。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-023":{"text":"非吸烟女性出现靠近胸膜的周边肺结节，最符合肺腺癌；腺癌是常见肺癌类型，亦可见于从不吸烟者。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-024":{"text":"潮红、腹泻、心动过速和支气管痉挛提示类癌综合征，可由具有神经内分泌功能的肺类癌分泌血清素等介质引起。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-025":{"text":"肺鳞癌与吸烟有强关联；腺癌常见于周边，小细胞癌多为中央型，因此其余描述与常见分布或类型不符。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-026":{"text":"肺癌可因异位ACTH引起库欣综合征，也可压迫交感链或上腔静脉；甲状腺功能亢进不是典型肺癌相关综合征。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-027":{"text":"抗生素无效的肺叶样阴影及痰中腺癌细胞提示肺腺癌沿肺泡壁生长的旧称细支气管肺泡癌；现多归入肺腺癌谱系。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-028":{"text":"长期吸烟、肺门中央肿块、支气管黏膜不规则及咯血，符合中央型肺鳞癌；肺腺癌更常为周边型。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-029":{"text":"旧称细支气管肺泡癌的肺腺癌亚型可沿肺泡播散，累及整叶并呈肺炎样实变。选项中的黏液性腺癌也可呈此型，题目有重叠，需复核。","references":[{"title":"Lung Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch06-en-single-030":{"text":"矽结节起于呼吸性细支气管周围间质而非肺泡腔，呈同心层状胶原纤维；矽肺还增加结核和纤维化风险。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-031":{"text":"可吸入的细小结晶二氧化硅被肺泡巨噬细胞吞噬后造成细胞损伤和炎症，反复损伤促使成纤维细胞活化及纤维化。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-032":{"text":"矽肺合并结核常发生于较晚期，结核空洞可更多、更大并有咯血；病程可明显加重，不宜概括为缓慢进展。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"},{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-033":{"text":"支气管扩张指支气管永久性扩张，源于管壁平滑肌和弹性组织被慢性炎症破坏；其余选项存在不准确或不典型之处。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-034":{"text":"煤工尘肺可并发结核、肺气肿、慢性支气管炎和肺心病；间皮瘤与石棉暴露关系密切，不是煤尘肺的典型并发症。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-035":{"text":"题干描述煤矿工人尘肺，但选项却谈矽结节和二氧化硅，疾病背景相互矛盾；煤尘与矽尘暴露需区分，答案需复核。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch06-en-single-036":{"text":"矽尘引起弥漫性间质纤维化，增加肺血管阻力并导致肺动脉高压，继而造成右心肥厚和肺心病。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-037":{"text":"二氧化硅被巨噬细胞吞噬后引发慢性炎症及成纤维细胞反应，形成矽结节与肺纤维化，而非化脓或纤维素性炎症。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"},{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-038":{"text":"早期矽结节富含吞噬二氧化硅的巨噬细胞，之后成纤维细胞产生胶原，逐步形成同心层状纤维结节。","references":[{"title":"Silicosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK594245/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-039":{"text":"支气管扩张的关键是慢性炎症破坏支气管壁平滑肌和弹性组织，导致支气管永久扩张；感染和阻塞常为诱因或维持因素。","references":[{"title":"Bronchiectasis","url":"https://www.ncbi.nlm.nih.gov/books/NBK525159/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-040":{"text":"病毒性肺炎主要累及肺间质，间隔增厚并有淋巴细胞等单核细胞浸润；肺泡腔大量中性粒细胞提示细菌性肺炎。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-041":{"text":"间质性肺炎的病变以肺泡间隔充血、水肿和单核细胞、淋巴细胞浸润为主，与肺泡腔内化脓性渗出不同。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-042":{"text":"病毒可在肺泡上皮细胞或巨噬细胞内形成核内或胞质包涵体，结合间质性炎症有助于识别病毒性肺炎。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-043":{"text":"流感病毒肺炎通常表现为间质性肺炎，肺泡间隔受累并有单核细胞浸润；大叶性实变更常见于肺炎链球菌感染。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-044":{"text":"病毒性肺炎可见受感染上皮细胞中的病毒包涵体，是比单纯间质炎症更具提示性的病理线索。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-045":{"text":"病毒感染常呈网状或不规则斑片状间质阴影，而不是整叶均匀实变；题干所述影像模式支持病毒性肺炎。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-046":{"text":"大叶性肺炎主要是肺泡内纤维素性炎症；支气管化脓不是其典型核心改变，支气管肺炎才以细支气管周围化脓灶为主。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-047":{"text":"军团菌肺炎多为细菌性肺泡炎，可呈大叶性或支气管肺炎；支原体、衣原体和病毒性肺炎较典型地累及间质。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-048":{"text":"军团菌可引起大叶性肺炎或融合性支气管肺炎，也可能有化脓性胸膜炎；单纯间质性炎症不是典型表现。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-049":{"text":"大叶性肺炎以肺泡腔纤维素性渗出为特征，病程中可伴中性粒细胞、红细胞及浆液成分。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-050":{"text":"小叶性肺炎是细支气管周围斑片状化脓性炎症，肺泡腔中常有大量中性粒细胞，而非纤维素主导。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-051":{"text":"支气管肺炎起自细支气管并向周围肺泡扩展，形成多灶、斑片状化脓性炎症；它与整叶纤维素性实变不同。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-052":{"text":"小叶性肺炎的典型病变是细支气管周围化脓性炎症，可呈多灶分布，常见于体弱或继发感染患者。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-053":{"text":"铁锈色痰是肺炎链球菌大叶性肺炎的经典线索；小叶性肺炎多为黏液脓性痰，且病灶由细支气管起始。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-054":{"text":"小叶性肺炎可并发脓胸、肺脓肿、败血症或呼吸衰竭；肺肉质变是大叶性肺炎渗出物机化的并发症。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-055":{"text":"小叶性肺炎以细支气管及邻近肺泡的化脓性炎症为主，故可见中性粒细胞和黏液脓性痰。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-056":{"text":"小叶性肺炎常从急性细支气管炎扩展形成支气管周围病灶；不是典型纤维素性整叶炎症。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-057":{"text":"大叶性肺炎主要是急性纤维素性炎症，不以肺泡内大量含铁血黄素的心衰细胞为特征；后者提示慢性肺淤血。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-058":{"text":"大叶性肺炎可累及整叶，常见肺炎链球菌和纤维素性渗出；肺泡及小支气管支架通常保留，结构广泛破坏并非特征。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-059":{"text":"肺炎最常见病原类别是细菌，典型社区获得性细菌包括肺炎链球菌；病毒、支原体等也可致病，但比例较低。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-060":{"text":"急性上呼吸道感染最常见病因为病毒，抗生素对病毒无效；细菌感染只占较小比例，需结合具体临床证据判断。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-061":{"text":"大叶性肺炎红色肝样期肺泡充满红细胞、中性粒细胞和纤维素，呈充血出血与纤维素渗出并存的外观。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-062":{"text":"大叶性肺炎的病理基础是肺泡腔纤维素性炎症，因此出现大片实变；化脓性渗出更符合支气管肺炎。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-063":{"text":"肺肉质变是肺炎渗出物未被清除而发生机化，纤维组织长入并使肺组织变实，属于大叶性肺炎的修复不良。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-064":{"text":"铁锈色痰常见于大叶性肺炎红色肝样期，此时肺泡内有红细胞、纤维素及中性粒细胞。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-065":{"text":"铁锈色痰转为黏液脓性痰反映红细胞破坏、炎症渗出转为纤维素和脓性成分，符合灰色肝样期。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-066":{"text":"含铁血黄素的肺泡巨噬细胞称心衰细胞，常见于慢性左心衰导致的肺淤血和出血后吞噬红细胞。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-067":{"text":"大叶性肺炎可并发肺脓肿、脓毒性休克、纤维素性胸膜炎及肺肉质变；支气管扩张不是通常急性并发症。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-068":{"text":"肺肉质变源于肺泡渗出物清除不足并机化，吞噬细胞数量减少或功能障碍会使纤维素持续存在并被纤维组织替代。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-069":{"text":"金黄色葡萄球菌具有组织破坏性，可造成坏死和化脓，因而肺脓肿是常见并发症之一。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-070":{"text":"慢性肺心病可见肺小动脉肌化、内膜增厚和毛细血管减少；中等动脉纤维素样坏死并非慢性肺高压的典型改变。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-071":{"text":"慢性肺心病可伴肺气肿、纤维化和小动脉重塑，并导致右室肥厚；肺小动脉纤维素样坏死不属于常见慢性改变。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-072":{"text":"肺气肿与吸烟、蛋白酶抗蛋白酶失衡及小气道阻塞有关；囊性纤维化并非其典型直接病因。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-073":{"text":"慢性支气管炎可见纤毛脱落、黏液腺增生、杯状细胞增多和鳞状化生；支气管软骨细胞非典型增生不是其特征。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-074":{"text":"慢性阻塞性肺气肿是慢性肺心病最常见病因之一，可通过长期缺氧和肺血管重塑导致肺动脉高压。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-075":{"text":"肺心病由肺部疾病造成肺动脉高压和右心负荷增加，可引发体循环淤血及右心衰；肺淤血通常源自左心衰。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-076":{"text":"慢性肺心病由长期肺动脉高压导致右室肥厚或扩张；肺动脉主干急性血栓栓塞通常造成急性肺心病。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch06-en-single-077":{"text":"慢性肺心病可见肺小动脉肌化、内膜增生和纤维弹性组织增多；小动脉玻璃样变不是典型肺高压重塑模式。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-078":{"text":"慢性肺心病常并发呼吸衰竭、心律失常、右室扩大及肺性脑病；心肌梗死通常源自冠脉病而非肺心病本身。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-079":{"text":"肺动脉主干或大分支血栓栓塞可突然升高肺动脉阻力，引起急性右室衰竭，即急性肺心病。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-080":{"text":"肺部疾病导致持续肺动脉高压，增加右心室后负荷，是肺心病形成的核心机制。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-081":{"text":"肺心病通常由慢性阻塞性肺病、矽肺或慢性结核等造成肺血管阻力升高；单纯间质性肺炎不属于经典病因选项。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-082":{"text":"慢性阻塞性肺气肿可造成长期低氧、肺血管收缩和重塑，是慢性肺心病最常见的基础病因。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-083":{"text":"病理诊断肺心病的经典标准之一是肺动脉瓣下约2厘米处右室壁厚度超过5毫米，反映右心室肥厚。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-084":{"text":"慢性支气管炎是常见的慢性阻塞性肺病类型，典型定义为连续两年、每年咳嗽咳痰至少三个月。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-085":{"text":"小叶中央型肺气肿首先累及腺泡中央的呼吸性细支气管，周边肺泡相对保留，常与吸烟有关。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-086":{"text":"小叶中央型肺气肿主要与吸烟和慢性细支气管炎相关；遗传性α1抗胰蛋白酶缺乏更典型导致全小叶型肺气肿。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-087":{"text":"α1抗胰蛋白酶不足使弹性蛋白酶活性缺少制衡，弥漫破坏肺泡壁，形成全小叶型肺气肿。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-088":{"text":"遗传性α1抗胰蛋白酶缺乏可导致年轻患者全小叶型肺气肿，常以下肺野受累较明显。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-089":{"text":"全小叶型肺气肿累及整个腺泡，从呼吸性细支气管到肺泡均匀扩张；小叶中央型则偏重腺泡中央。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch06-en-single-090":{"text":"肺气肿的关键是肺泡壁破坏、弹性回缩下降和气道阻塞；鳞状化生属于慢性支气管炎常见上皮改变。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-091":{"text":"慢性阻塞性细支气管炎导致小气道狭窄及呼气受限，是肺气肿发生和进展的重要机制；吸烟是主要危险暴露。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-092":{"text":"肺气肿按定义是终末细支气管远端含气腔永久扩大并伴肺泡壁破坏，终末细支气管本身不属于受累远端腔隙。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-093":{"text":"桶状胸、叩诊过清音和呼吸音减弱提示肺气肿，典型改变包括肺泡扩张、肺泡隔破坏及融合；广泛纤维化并不典型。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-094":{"text":"胸膜下及小叶间隔旁串珠样气泡提示间质性肺气肿，即空气进入肺间质，而非肺泡腔本身扩张。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-095":{"text":"慢性支气管炎与肺气肿常共同构成慢阻肺，持续炎症和小气道阻塞促进肺泡壁破坏及肺气肿形成。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-096":{"text":"长期烟雾刺激导致支气管上皮鳞状化生，是慢性支气管炎的常见组织改变，也会损害黏液纤毛清除功能。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-097":{"text":"小气道黏膜水肿、黏液增多及炎症造成管腔阻塞，是慢性支气管炎通气障碍的主要基础。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch06-en-single-098":{"text":"季节性慢性咳嗽咳痰符合慢性支气管炎；它可并发肺气肿、肺心病并与吸烟相关，但不直接导致大叶性肺炎。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-099":{"text":"慢性支气管炎与烟草烟雾、空气污染及病毒或常见细菌感染有关；支原体不是其主要长期致病因素。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch06-en-single-100":{"text":"慢性支气管炎常有杯状细胞和黏液腺增生、纤毛损伤及鳞状化生；支气管壁纤维弹性增生不是本病标志性变化。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch06-en-single-101":{"text":"黏液腺肥大及杯状细胞增生增加气道黏液分泌，解释慢性支气管炎患者长期咳痰；单纯鳞状化生不直接产生痰液。","references":[{"title":"Chronic Obstructive Pulmonary Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK559281/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-001":{"text":"暴饮酒后上腹痛向背部放射，淀粉酶和脂肪酶升高，符合急性胰腺炎。胰酶外漏会消化周围脂肪，造成胰周脂肪坏死；钙皂是脂肪酸与钙结合的结果。","references":[{"title":"Acute Pancreatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543795/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-002":{"text":"无痛性进行性黄疸、体重下降和CA19-9升高提示胰头癌压迫胆总管，导致胆汁淤积。胆石症通常引起绞痛，不能解释持续消瘦和肿瘤标志物升高。","references":[{"title":"Acute Pancreatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543795/"},{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-003":{"text":"胆囊结石及胆囊壁增厚符合胆石症并慢性炎症。胆汁胆固醇过饱和、胆囊排空不足会促进胆固醇结晶形成；溶血则更易形成色素结石。","references":[{"title":"Cholelithiasis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459370/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-004":{"text":"发热、右上腹绞痛和中性粒细胞增多，肝酶正常，符合急性胆囊炎而非肝炎。胆囊管结石阻塞后引起胆囊壁炎症，常有右上腹压痛。","references":[{"title":"Cholelithiasis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459370/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-005":{"text":"农民、门静脉高压表现及结节性肝脏提示血吸虫病造成的肝纤维化。虫卵沉积引发门管区肉芽肿和纤维化，可致腹水；寄生虫相关性肝病需结合病理图确认。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-006":{"text":"Kayser–Fleischer角膜环和神经精神改变是肝豆状核变性的线索，组织中铜沉积增加。Wilson病通常血清铜蓝蛋白降低，题干所说“升高”与诊断相矛盾，需复核此处。","references":[{"title":"Wilson Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK441990/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch07-en-single-007":{"text":"急性肝衰竭、凝血异常、脑病及肝脏缩小软化，符合暴发性肝炎的大块肝细胞坏死；局灶或桥接坏死通常不造成如此广泛的肝缩小。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-008":{"text":"桥接坏死指肝细胞坏死区跨越结构区域相连，例如由门管区延伸至邻近中央静脉，提示较重的慢性肝炎活动。单纯界板破坏称界面性肝炎。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-009":{"text":"慢性肝损伤使肝星状细胞活化并转化为产胶原的肌成纤维样细胞，胶原沉积形成纤维间隔，包绕再生结节而构成肝硬化。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-010":{"text":"长期无症状且持续HBsAg阳性、无抗-HBs，提示慢性携带。乙肝围产期传播更容易形成持续感染；成人急性感染则多能清除病毒。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-011":{"text":"大量呕血、腹水和脾大提示门静脉高压及食管胃底静脉曲张破裂，最符合肝硬化。急性肝炎或胆石症不能解释脾大和腹水。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-012":{"text":"题目描述肝脏大体图并询问摄入物，结合中国南方肝癌高发背景，霉变花生中的黄曲霉毒素可损伤肝细胞并促进肝细胞癌发生。应与血吸虫病相关的门脉纤维化区分。","references":[{"title":"Hepatocellular Carcinoma","url":"https://www.ncbi.nlm.nih.gov/books/NBK350558/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-013":{"text":"低白蛋白、腹水及肝功能受损提示慢性肝炎进展为肝硬化；题干所述三色染色强调纤维化。乙肝可造成慢性炎症、肝细胞坏死和纤维隔形成。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-014":{"text":"慢性乙肝肝硬化伴既往消化道出血及合成功能下降，提示门静脉高压和肝功能失代偿。腹水、脾大、腹壁静脉曲张及蜘蛛痣均可出现，因此选“以上皆是”。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"},{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-015":{"text":"乙肝康复后出现抗-HBs表示获得保护性免疫，通常伴随HBsAg消失。抗-HBc可长期存在，单独阳性不能作为恢复的特异标志。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-016":{"text":"可导致慢性肝炎和肝硬化的病毒主要是HBV、HCV及HDV；甲肝和戊肝通常为急性感染，不会常规演变为慢性肝病。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-017":{"text":"慢性HBV感染多年后出现体重下降、腹围迅速增加及腹痛，提示肝细胞癌。AFP可用于支持诊断；凝血酶原时间和氨升高反映肝衰，不特异指向肿瘤。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-018":{"text":"IgM抗HAV阳性并有急性黄疸和转氨酶升高，提示急性甲型肝炎；抗-HBs和抗-HBc则提示既往乙肝感染或免疫状态，而非当前急性乙肝。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-019":{"text":"肝硬化失代偿表现为腹水、黄疸、低白蛋白、凝血延长和高氨；阳性HBsAg提示慢性乙肝为可能病因。AFP升高提示肝癌而非单纯肝硬化。","references":[{"title":"Hepatocellular Carcinoma","url":"https://www.ncbi.nlm.nih.gov/books/NBK350558/"},{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-020":{"text":"肝组织脂肪变、Mallory-Denk小体、中性粒细胞浸润和肝细胞坏死是酒精性肝炎的典型组合。病毒血清学阴性也支持长期酒精相关损伤。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-021":{"text":"HBsAg阳性、结节状肝脏和AFP升高提示慢性乙肝背景下肝硬化及肝细胞癌风险；胆管腺癌并非此类患者最可能的肿瘤类型。","references":[{"title":"Hepatocellular Carcinoma","url":"https://www.ncbi.nlm.nih.gov/books/NBK350558/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-022":{"text":"酒精性肝硬化显著增加肝细胞癌风险。长期肝细胞损伤与再生造成基因改变，肝癌是肝硬化的重要恶性并发症。","references":[{"title":"Hepatocellular Carcinoma","url":"https://www.ncbi.nlm.nih.gov/books/NBK350558/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-023":{"text":"大泡性脂肪变合并Mallory小体提示酒精性肝炎；Mallory-Denk小体由受损肝细胞内细胞骨架蛋白聚集形成，并常伴中性粒细胞炎症。","references":[{"title":"Pneumonia","url":"https://www.ncbi.nlm.nih.gov/books/NBK526116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-024":{"text":"持续六个月HBsAg阳性且没有症状或肝酶异常，符合慢性乙肝携带状态。此人已感染，不应接种乙肝疫苗；单次急性感染通常会有抗-HBc等证据。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-025":{"text":"持续一年肝炎及门管区淋巴细胞聚集、轻度脂肪变提示慢性丙型肝炎常见组织图景；脾切除史并不能确定病原。勘误表未给标准答案，需复核题目答案。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"needs_review","originalAnswer":[]},"pathology-ch07-en-single-026":{"text":"食用河螺后出现自限性急性肝炎，提示经粪口传播的甲型肝炎；急性感染期通常可检出抗-HAV IgM。原题答案栏空缺，需复核。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"needs_review","originalAnswer":[]},"pathology-ch07-en-single-027":{"text":"HBsAg阳性、AFP升高和肝内肿块提示肝细胞癌，慢性乙肝可通过反复坏死再生促进癌变。高脂饮食并非本题所述HBV相关癌变机制，故该项为错误描述。","references":[{"title":"Hepatocellular Carcinoma","url":"https://www.ncbi.nlm.nih.gov/books/NBK350558/"},{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-028":{"text":"不同肝炎病毒造成慢性化的概率差异很大：HCV及HBV可持续感染，HDV需依赖HBV并可加重慢性病程。转氨酶单次升高幅度不足以预测是否进展。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-029":{"text":"活检见界板破坏并有炎症从门管区进入小叶，符合慢性活动性肝炎；持续HBsAg阳性是乙肝感染的血清学依据。抗-HBs阳性反而表示免疫或恢复。","references":[{"title":"Viral Hepatitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK554549/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-030":{"text":"阑尾周围炎症伴腔内类癌样神经内分泌细胞，染色质颗粒及嗜铬粒蛋白阳性支持阑尾类癌。肿瘤阻塞腔道可诱发急性阑尾炎。","references":[{"title":"Appendicitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK493193/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-031":{"text":"弥漫腹膜刺激征、腹腔混浊液和革兰阴性杆菌提示阑尾穿孔后腹膜炎；单纯急性阑尾炎通常没有腹腔游离感染液。","references":[{"title":"Appendicitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK493193/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-032":{"text":"转移性右下腹痛、发热和反跳痛提示急性阑尾炎，常伴白细胞增多。妊娠、胰腺炎或幽门螺杆菌感染都不能解释典型局部腹膜刺激征。","references":[{"title":"Appendicitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK493193/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-033":{"text":"题图可见胞内大黏液空泡将细胞核挤向一侧，呈印戒样特征。该形态需与答案A黏液腺癌区分，单凭现有图像难以确认选项，故保留复核。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch07-en-single-034":{"text":"结肠腺癌细胞出现在腹水中提示腹膜播散。肿瘤穿透浆膜可直接侵犯表面，脱落癌细胞也可在腹膜种植，故两种途径均可能。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-035":{"text":"结肠癌切除后CEA再升高并出现肝内多个肿块，最符合血行转移。结肠静脉回流经门静脉进入肝脏，肝是结直肠癌常见远处转移部位。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-036":{"text":"既往绒毛状腺瘤伴高级别异型增生，后出现环周浸润性肿块和肠系膜淋巴结，提示腺瘤进展为结肠腺癌。腺瘤是常见癌前病变。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-037":{"text":"年轻患者结肠内布满腺瘤性息肉，符合家族性腺瘤性息肉病。其根本病因是生殖系APC抑癌基因突变，未经预防性治疗几乎必然发生结直肠癌。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"},{"title":"Lynch Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK1211/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-038":{"text":"右侧结肠癌常与错配修复基因缺陷及微卫星不稳定相关，尤其见于Lynch综合征。APC突变更多见于经典腺瘤—癌序列。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-039":{"text":"管状绒毛状腺瘤属于结直肠癌前病变，切除后需按风险规律复查结肠镜；发现腺瘤并不自动意味着所有家属都需筛查，除非有遗传或家族风险。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-040":{"text":"大量结肠腺瘤性息肉并有年轻发病家族史，符合家族性腺瘤性息肉病，其典型机制为APC突变。Lynch综合征通常没有数百个腺瘤。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"},{"title":"Lynch Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK1211/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-041":{"text":"病灶局限于黏膜内，尚未穿透黏膜肌层，几乎没有淋巴或远处转移风险，因此无需对该病灶进行转移检查；仍应按腺瘤风险计划后续结肠镜。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-042":{"text":"直肠肿块及便潜血符合结直肠腺癌风险情境。高脂饮食与结直肠癌风险相关；溃疡性结肠炎和克罗恩病也可提高风险，但题干未给慢性炎症史。","references":[{"title":"Colon Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK470380/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-043":{"text":"溃疡性结肠炎累及直肠并连续向近端延伸，已有假息肉和异型增生；长期广泛结肠炎显著增加结肠腺癌风险。瘘管更典型于克罗恩病。","references":[{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-044":{"text":"溃疡性肿块占据大部分肠壁并伴CEA升高，符合浸润性结肠腺癌。腺瘤通常是黏膜内息肉样病变，未侵入时不形成大块壁内肿物。","references":[{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-045":{"text":"多发腺瘤和右侧结肠癌，加上题干的家族史背景，考虑Lynch综合征。经典FAP通常有数百至数千枚腺瘤，而不只是所述少数息肉。","references":[{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-046":{"text":"跳跃性病灶、透壁性炎症、非干酪性肉芽肿和肛周瘘是克罗恩病的典型组合；溃疡性结肠炎通常连续累及黏膜且从直肠开始。","references":[{"title":"Crohn Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK436021/"},{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-047":{"text":"右下腹局灶性肠炎、节段性受累和非干酪性肉芽肿提示克罗恩病，也称区域性肠炎。肠结核常见干酪样肉芽肿及横向溃疡。","references":[{"title":"Crohn Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK436021/"},{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-048":{"text":"从直肠连续向近端延伸的脆弱黏膜、隐窝脓肿及假息肉符合溃疡性结肠炎。克罗恩病更常呈跳跃病灶和透壁性病变。","references":[{"title":"Crohn Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK436021/"},{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-049":{"text":"隐窝腔内聚集大量中性粒细胞形成隐窝脓肿，是活动性溃疡性结肠炎的镜下表现。肉芽肿则由组织细胞构成，位置和形态不同。","references":[{"title":"Crohn Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK436021/"},{"title":"Ulcerative Colitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK459282/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-050":{"text":"严重心衰可导致肠系膜低灌注，出现结肠节段性糜烂和腹泻，符合缺血性结肠炎。抗生素相关伪膜性肠炎需有感染证据及典型黏膜伪膜。","references":[{"title":"Clostridioides difficile Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK431054/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-051":{"text":"广谱抗生素后出现肠麻痹和血便，切除肠段见黄白色黏附性伪膜，提示艰难梭菌毒素导致的伪膜性结肠炎。抗生素破坏正常菌群促使其过度生长。","references":[{"title":"Clostridioides difficile Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK431054/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-052":{"text":"长期广谱抗生素后出现严重腹泻且粪便毒素阳性，符合艰难梭菌相关伪膜性肠炎；肠黏膜表面可见纤维素和炎性细胞构成的伪膜。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-053":{"text":"未洗净蔬菜后急性发热、黏液脓血便提示细菌性痢疾；志贺菌经粪口传播并侵犯结肠黏膜，常引起里急后重和脓血便。","references":[{"title":"Bacterial Gastroenteritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK551643/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-054":{"text":"志贺菌性痢疾造成结肠黏膜坏死、渗出和表面纤维素脓性伪膜。假息肉是慢性炎症修复后残留黏膜突起，不是急性感染特征。","references":[{"title":"Bacterial Gastroenteritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK551643/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-055":{"text":"回盲部溃疡、狭窄及肉芽肿，加上肺门钙化提示结核感染；结核菌素试验常阳性。肠结核多为横向溃疡，肉芽肿常可干酪样坏死。","references":[{"title":"Tuberculosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-056":{"text":"旅行后血黏液便继而出现肝右叶复杂脓肿，符合溶组织内阿米巴引起的肠阿米巴病及阿米巴肝脓肿。病原可经门静脉由结肠到肝脏。","references":[{"title":"Gastrointestinal Infections","url":"https://www.ncbi.nlm.nih.gov/books/NBK556115/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-057":{"text":"发热、腹泻、脾大、白细胞减少和肝酶升高提示伤寒。实验室暴露后出现相符症状，最可能接触伤寒沙门菌；志贺菌一般不造成典型脾大及白细胞减少。","references":[{"title":"Bacterial Gastroenteritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK551643/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-058":{"text":"年轻患者反复右下腹痛和贫血，但常规胃镜与结肠镜阴性，提示小肠病变或出血。Meckel憩室可含异位胃黏膜并溃疡出血，是儿童及年轻人消化道出血原因。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-059":{"text":"婴儿结肠扩张、便秘和直肠壁缺乏肌间及黏膜下神经节细胞，说明先天性肠神经节细胞缺如，即Hirschsprung病。无神经节段持续收缩导致近端扩张。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-060":{"text":"胃壁梭形肿瘤且CD117阳性提示胃肠道间质瘤，常由C-KIT或PDGFRA信号异常驱动。平滑肌肉瘤不表达典型CD117。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-061":{"text":"胃黏膜相关淋巴组织B细胞单克隆增殖，且有幽门螺杆菌慢性胃炎史，提示胃MALT淋巴瘤。早期病例根除幽门螺杆菌可使肿瘤消退。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-062":{"text":"双侧卵巢转移性印戒细胞癌称Krukenberg瘤，最常见原发灶是胃腺癌。双侧卵巢受累和CEA升高支持转移，而非原发卵巢肿瘤。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-063":{"text":"胃癌穿透胃壁并在腹膜及肠、脾表面形成多发结节，说明局部侵犯和腹膜种植；左锁骨上淋巴结提示淋巴转移。未见肝病灶，无法支持血行转移。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-064":{"text":"胃肿瘤呈向腔内突出的团块状、多结节隆起外观，符合息肉型胃癌。溃疡型以中央凹陷为主，浸润型则表现为胃壁弥漫增厚僵硬。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-065":{"text":"胃腺癌患者同时有黏膜苍白变薄及既往慢性胃黏膜异常，符合慢性萎缩性胃炎这一癌前背景。弥漫型癌和皮革胃需见弥漫性壁内浸润。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-066":{"text":"小于1厘米的黏膜内胃腺癌在大体上常呈息肉样突出型，属于早期胃癌的一种外观。病变仍限于黏膜，不能仅凭尺寸推断浸润深度。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-067":{"text":"早期胃癌的定义是癌组织局限于黏膜或黏膜下层，不论是否已有淋巴结转移；侵犯固有肌层即不再属于早期胃癌。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-068":{"text":"胃壁弥漫增厚僵硬、胃缩小及肝内转移符合进展期胃腺癌。自身免疫性胃炎造成慢性萎缩和肠化生，是胃腺癌的癌前背景之一。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-069":{"text":"胃窦巨大溃疡性肿块造成胃出口梗阻，最常见恶性肿瘤是胃腺癌。胃肠道间质瘤通常起自胃壁间叶，常呈壁内或外生性肿块。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-070":{"text":"幽门螺杆菌相关慢性胃炎及胃癌在东亚较常见。病变限于黏膜下仍属于早期胃癌，可有淋巴结转移，故不能据此排除转移。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-071":{"text":"胃体缩小、蠕动减弱及黏膜广泛异常提示皮革胃样弥漫型胃癌，常为印戒细胞癌并属进展期；列出的描述均可成立。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-072":{"text":"小而边界清楚的胃溃疡较可能是良性消化性溃疡，但仍需内镜取样排除癌。良性溃疡常与幽门螺杆菌或非甾体抗炎药有关。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-073":{"text":"穿孔性十二指肠溃疡与幽门螺杆菌感染密切相关；细菌导致慢性胃炎并改变胃酸调节。膈下游离气体说明消化道穿孔。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-074":{"text":"幽门螺杆菌性消化性溃疡可出血、穿孔或造成幽门梗阻；其与胃癌有关，但相较这些溃疡并发症，患者不易由单纯溃疡直接发展胃腺癌。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-075":{"text":"幽门螺杆菌感染常累及胃窦并增加胃酸分泌，可促进十二指肠溃疡。自身免疫性胃体萎缩则导致低酸和恶性贫血。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-076":{"text":"胃窦浅表溃疡最常与幽门螺杆菌相关，可通过尿素酶呼气试验检出。胃泌素显著升高则需考虑胃泌素瘤等情况。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-077":{"text":"大细胞性贫血、低网织红细胞和萎缩性胃炎提示恶性贫血。自身免疫性胃炎主要破坏胃体和胃底壁细胞，导致内因子缺乏。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-078":{"text":"活检所示特殊染色用于显示胃窦慢性胃炎中的微生物，结合既往呼气试验阳性，最符合幽门螺杆菌感染。该菌与慢性活动性胃炎相关。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-079":{"text":"幽门螺杆菌长期感染可造成慢性胃炎、腺体萎缩和肠上皮化生，增加胃癌风险；自身免疫抗体阴性使自身免疫性胃炎较不可能。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-080":{"text":"大细胞性贫血提示维生素B12缺乏的恶性贫血，自身免疫性胃体萎缩可产生抗内因子抗体并妨碍B12吸收。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-081":{"text":"胃窦慢性非特异性胃炎常与幽门螺杆菌相关并可增加胃癌风险；恶性贫血通常源于自身免疫性胃体萎缩，不符合本病例。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-082":{"text":"大量阿司匹林抑制胃黏膜前列腺素保护作用，可引起急性糜烂性胃炎和出血。慢性萎缩、异型增生或胃癌需要更长期的病程。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-083":{"text":"Steiner银染可显示胃黏膜表面的弯曲杆菌，结合胃炎和胃窦皱襞增厚，最符合幽门螺杆菌。该菌可引起慢性活动性胃炎。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"},{"title":"Helicobacter pylori Infection","url":"https://www.ncbi.nlm.nih.gov/books/NBK590949/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-084":{"text":"短时间内发生的急性胃黏膜损伤以中性粒细胞炎症和糜烂为主，去除刺激后常在数日内恢复；恶性贫血和肠化生属于慢性病变。","references":[{"title":"Gastritis and Peptic Ulcer Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK2461/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-085":{"text":"中段食管鳞癌与吸烟、饮酒等有关，Barrett食管是远端食管腺癌的癌前病变，不是鳞癌前驱病变。原题答案将两种癌的前驱病变混淆，需复核。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch07-en-single-086":{"text":"食管呈长段狭窄伴粗糙黏膜，提示肿瘤沿食管壁浸润生长造成环周增厚和管腔变窄，属于浸润型大体形态。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-087":{"text":"食管中段鳞癌与高温饮食、烟酒及营养因素相关，水果摄入通常具有保护作用；题目所给“高水果饮食”与标准答案方向相反，需复核。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch07-en-single-088":{"text":"食管中段鳞癌的风险因素包括长期饮酒和吸烟；胃食管反流及Barrett食管更主要关联远端食管腺癌。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-089":{"text":"中段食管溃疡性肿块且家族多发，组织学最符合食管鳞状细胞癌；Barrett相关腺癌多位于远端食管。","references":[{"title":"Gastrointestinal Cancers","url":"https://www.ncbi.nlm.nih.gov/books/NBK586002/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-090":{"text":"长期反流后出现远端食管肿块，最符合腺癌，可由Barrett食管的肠上皮化生和异型增生演变而来；鳞癌多发生在中段。","references":[{"title":"Barrett Esophagus","url":"https://www.ncbi.nlm.nih.gov/books/NBK430979/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-091":{"text":"胃食管反流使远端食管鳞状上皮被含杯状细胞的柱状上皮取代，称Barrett食管，是肠化生而非鳞状化生，并增加腺癌风险。","references":[{"title":"Barrett Esophagus","url":"https://www.ncbi.nlm.nih.gov/books/NBK430979/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-092":{"text":"胃食管反流引起的Barrett食管呈红色绒毛状柱状上皮和杯状细胞肠化生，可进一步发生异型增生并发展为食管腺癌。","references":[{"title":"Barrett Esophagus","url":"https://www.ncbi.nlm.nih.gov/books/NBK430979/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-093":{"text":"活检显示基底层增生及乳头延长，符合反流性食管炎；可出现狭窄、Barrett食管及腺癌风险，但不典型导致鳞癌。","references":[{"title":"Barrett Esophagus","url":"https://www.ncbi.nlm.nih.gov/books/NBK430979/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-094":{"text":"胃灼热和胃食管交界以上红色舌状黏膜，结合活检肠化生，符合长期胃食管反流造成的Barrett食管。","references":[{"title":"Barrett Esophagus","url":"https://www.ncbi.nlm.nih.gov/books/NBK430979/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch07-en-single-095":{"text":"HIV感染者出现食管多发溃疡且活检有包涵体，提示巨细胞病毒性食管炎；念珠菌通常形成白色斑块而非溃疡。","references":[{"title":"Esophagitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK442012/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch07-en-single-096":{"text":"免疫抑制患者食管中下段出现小而界限清楚的浅溃疡，提示单纯疱疹病毒感染；HSV常形成凿孔样溃疡。","references":[{"title":"Esophagitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK442012/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch07-en-single-097":{"text":"吞咽困难、食管上段扩张及下段缺乏肌间神经节细胞，符合贲门失弛缓症。下食管括约肌不能松弛造成食物潴留和误吸。","references":[{"title":"Achalasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK519515/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch07-en-single-098":{"text":"乙肝感染伴突发大量呕血，提示肝硬化门静脉高压导致食管静脉曲张破裂。没有既往呕吐等诱因，不支持食管撕裂。","references":[{"title":"Hepatic Cirrhosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK482419/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch07-en-single-099":{"text":"剧烈呕吐后突发大量呕血，最符合Mallory–Weiss黏膜撕裂，常发生于胃食管交界附近；完整壁破裂则为更危重的Boerhaave综合征。","references":[{"title":"Esophagitis","url":"https://www.ncbi.nlm.nih.gov/books/NBK442012/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-001":{"text":"IgA肾病是全球最常见的原发性肾小球肾炎，常见表现为上呼吸道感染同时或之后出现肉眼血尿。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-002":{"text":"糖尿病肾病是导致终末期肾病最常见的原因之一，长期高血糖造成肾小球基底膜增厚、系膜扩张及逐步肾小球硬化。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-003":{"text":"长期接触β-萘胺等芳香胺染料并出现无痛性肉眼血尿，提示膀胱尿路上皮癌。尿培养阴性且没有肾小球性蛋白尿支持泌尿道肿瘤。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-004":{"text":"大量蛋白尿、低白蛋白及基底膜增厚并有颗粒状免疫染色，符合膜性肾病；其免疫复合物沉积于肾小球上皮下并激活补体。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-005":{"text":"感染后短期内反复肉眼血尿和系膜增生提示IgA肾病，特征是含IgA免疫复合物沉积于系膜。链球菌后肾炎通常在感染后数周出现。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-006":{"text":"原资料未提供本题所需图片，因此无法核对影像判断。仅从文字看，幼儿肾脏实性肿块伴血尿可考虑Wilms肿瘤，但需图片复核。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch08-en-single-007":{"text":"大量蛋白尿、补体和IgG呈毛细血管壁颗粒状沉积，提示膜性肾病；电镜应见上皮下电子致密物沉积。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-008":{"text":"严重失血和持续低血压后出现少尿、肌酐升高并经历多尿恢复期，符合缺血性急性肾小管坏死，可见肾小管基底膜破裂。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-009":{"text":"双肾被大量大小不一囊肿取代提示常染色体显性多囊肾，囊肿压迫和肾素系统激活常引起高血压。","references":[{"title":"Autosomal Dominant Polycystic Kidney Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK532934/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-010":{"text":"膀胱大体图见明显小梁状增厚和憩室样突起，提示长期出口梗阻，最常由良性前列腺增生造成；PSA可轻度升高。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-011":{"text":"肾炎综合征伴低补体、毛细血管内增生、IgG/C3颗粒沉积和上皮下驼峰样沉积，是感染后肾小球肾炎的典型组合。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-012":{"text":"儿童选择性大量蛋白尿、肾功能正常且激素治疗有效，符合微小病变病；电镜显示足细胞足突弥漫融合或消失。","references":[{"title":"Minimal Change Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-013":{"text":"血尿与上呼吸道感染几乎同步出现并反复，提示IgA肾病；免疫荧光可见系膜区IgA颗粒状沉积。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-014":{"text":"老年女性尿道外口出现逐渐增大、溃疡出血的疣状肿块，最可能为尿道鳞状细胞癌；良性乳头状瘤通常较小且不溃破。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-015":{"text":"膀胱肿瘤呈指状乳头并有纤维血管轴，未侵犯固有层或肌层，符合非浸润性乳头状尿路上皮癌。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-016":{"text":"急性大肠杆菌膀胱炎以中性粒细胞浸润为主；淋巴浆细胞浸润更偏慢性炎症，肉芽肿则提示特殊感染。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-017":{"text":"婴儿肾肿瘤出现胚芽、未成熟小管和肾小球样结构，符合Wilms肿瘤；WT1基因异常与其发生相关。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-018":{"text":"成人肾上极肿块和肉眼血尿提示肾癌，但标准答案C的“未分化间叶细胞”并非经典肾细胞癌形态；透明细胞癌选项E更符合，需复核答案。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch08-en-single-019":{"text":"舒张压极高并有增生性小动脉病变，提示恶性高血压；肾表面可见点状出血，形成所谓“跳蚤咬”样外观。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-020":{"text":"双肾缩小不规则、肾盂扩张和肾盏钝化伴慢性间质炎症，符合慢性肾盂肾炎；肾小管萎缩扩张并充满胶样管型，称甲状腺化。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-021":{"text":"近端和远端小管上皮灶性坏死、扁平化、基底膜破裂且间质水肿，符合急性肾小管坏死，而非炎症性肾盂肾炎。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-022":{"text":"致密沉积病的带状致密沉积符合旧分类中的膜增生性肾小球肾炎Ⅱ型；现代分类将其归入C3肾小球病。题目选项采用旧名称，故D可对应，但应注意分类更新。","references":[{"title":"C3 Glomerulopathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK609090/"},{"title":"C3 Glomerulopathy Consensus","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3842953/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-023":{"text":"儿童肾病综合征、光镜近乎正常、电镜足突融合而无免疫沉积，符合微小病变病；儿童常对糖皮质激素反应良好。","references":[{"title":"Minimal Change Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-024":{"text":"全身水肿、低白蛋白、高胆固醇、重度蛋白尿及脂肪管型组成肾病综合征。肾小球滤过屏障通透性增加导致白蛋白大量丢失。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-025":{"text":"前列腺腺癌最常起自外周区，常可经直肠指检触及硬结；移行区结节性增生则围绕尿道并导致排尿梗阻。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-026":{"text":"多年尿频、夜尿、尿流迟缓及前列腺增大，符合良性前列腺增生的结节性改变；PSA轻度升高可由增生造成。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-027":{"text":"直肠指检硬结及拥挤小腺体、核仁明显的异型细胞，支持前列腺腺癌；良性增生腺体排列较规则且有基底细胞层。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-028":{"text":"儿童激素敏感性肾病综合征并脂肪尿，最符合微小病变病；足细胞足突融合是关键电镜所见。","references":[{"title":"Minimal Change Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-029":{"text":"抗生素治疗后发热、皮疹、嗜酸性粒细胞增多和急性肾损伤，典型提示药物性间质性肾炎（选项B）。答案键给感染后肾炎，与线索不符，需复核。","references":[{"title":"Acute Interstitial Nephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK557537/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch08-en-single-030":{"text":"心梗后低血压及组织灌注不足，随后肌酐上升并出现颗粒管型，说明缺血性急性肾小管坏死。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-031":{"text":"两岁儿童肾脏肿物由胚芽样小蓝细胞及原始小管构成，符合Wilms肿瘤的胚胎性肾组织成分。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-032":{"text":"微小病变病造成肾小球滤过屏障选择性损伤，表现为大量蛋白尿，达到肾病范围；不同患者脂尿或高脂血症程度可有差异。","references":[{"title":"Minimal Change Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-033":{"text":"重度吸烟者无痛血尿且尿细胞学见尿路上皮异型细胞，膀胱镜未见病灶，提示上尿路肿瘤，肾盂尿路上皮癌可逃过膀胱镜检查。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-034":{"text":"成人肾病综合征最常见的原发性病因之一是膜性肾病，特征为肾小球毛细血管壁弥漫增厚和上皮下免疫沉积。","references":[{"title":"Membranous Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK559169/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-035":{"text":"低补体、颗粒状免疫沉积和上皮下驼峰样电子致密物是链球菌感染后肾小球肾炎的典型组合。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-036":{"text":"肾病综合征的定义性蛋白尿阈值为每日超过3.5克，常伴低白蛋白、水肿和高脂血症。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-037":{"text":"儿童大量蛋白尿且激素治疗后完全缓解，提示微小病变病；预期电镜主要异常是足细胞足突弥漫消失。","references":[{"title":"Minimal Change Disease","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-038":{"text":"宽大管型由扩张肾单位中形成，常见于慢性肾功能衰竭；贫血和低钙也可出现，但特异性较低。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-039":{"text":"快速进展性肾小球肾炎造成毛细血管袢破坏，纤维蛋白和炎症介质进入鲍曼囊，刺激壁层上皮增生形成新月体。","references":[{"title":"Rapidly Progressive Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK557430/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-040":{"text":"血尿、红细胞管型、高血压及低补体提示感染后肾小球肾炎；儿童多数预后良好，可自行恢复。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-041":{"text":"急性肾小管坏死使小管重吸收钠能力下降，故尿钠排泄分数升高；肾前性状态则通常保留钠。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-042":{"text":"乳头状肿瘤由异型尿路上皮覆盖纤维血管轴，且未侵犯固有层或肌层，诊断为非浸润性乳头状尿路上皮癌。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-043":{"text":"肾上极实质肿瘤最常见为肾细胞癌，成人中经典透明细胞型细胞富含脂质和糖原，胞质清亮。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-044":{"text":"全身水肿、低白蛋白、高胆固醇、重度蛋白尿和脂肪尿构成肾病综合征，反映肾小球蛋白滤过屏障受损。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-045":{"text":"肺内透明细胞癌样转移灶需考虑肾细胞癌，但本题标准答案给胰腺。胰腺腺癌通常不是透明细胞肿瘤的典型原发来源，答案可能错误，需复核。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch08-en-single-046":{"text":"排尿困难伴前列腺增大，活检见腺体和间质增生且保留双层上皮，符合良性前列腺增生；腺癌常失去基底细胞层。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-047":{"text":"急性发热、寒战、排尿疼痛及前列腺触痛提示急性细菌性前列腺炎；慢性前列腺炎通常病程反复或迁延。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-048":{"text":"咽炎后约十日出现茶色尿、红细胞管型、ASO升高及上皮下驼峰沉积，符合急性链球菌感染后肾小球肾炎。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-049":{"text":"乙肝后肾炎表现为免疫复合物介导的肾小球损伤，可见颗粒状免疫球蛋白沉积；线性IgG染色更提示抗基底膜病。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-050":{"text":"肾脏切面可见多个不规则皮质瘢痕并牵拉肾盏，符合慢性肾盂肾炎，而非弥漫性急性炎症。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-051":{"text":"肾小管上皮灶性坏死、扁平化和基底膜破裂而缺乏急性炎细胞，符合急性肾小管坏死。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-052":{"text":"链球菌咽炎后十日出现血尿，潜伏期及肾炎表现支持感染后肾小球肾炎，电镜可见上皮下驼峰样沉积。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-053":{"text":"Wilms肿瘤典型三相结构包括胚芽、上皮性小管和间叶性基质，常见于幼儿腹部肿块。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-054":{"text":"恶性高血压可使小动脉壁平滑肌增生，形成同心洋葱皮样层状增厚，称增生性小动脉硬化。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-055":{"text":"儿童出现水肿、红褐色尿和血尿蛋白尿，提示急性肾小球肾炎；若为感染后肾炎，电镜可见上皮下驼峰样免疫沉积。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-056":{"text":"红细胞管型、蛋白尿及肾小球新月体提示快速进展性肾炎；抗肾小球基底膜病可造成严重毛细血管壁损伤和新月体形成。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-057":{"text":"幼儿水肿和单纯大量蛋白尿而无血尿或管型，符合微小病变病；电镜显示足细胞足突融合。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-058":{"text":"两岁儿童肾脏来源的腹部肿块最常见为肾母细胞瘤，即Wilms肿瘤；肾细胞癌主要见于成人。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-059":{"text":"硬结节状前列腺、PSA明显升高及椎体成骨性转移，符合前列腺腺癌；其骨转移常呈成骨性。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch08-en-single-060":{"text":"幼儿伴性腺发育异常及肾源性腹部肿块，提示Wilms肿瘤相关综合征；WT1基因参与肾脏和性腺发育。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-061":{"text":"Wilms肿瘤由胚芽、上皮和间叶成分组成，可见原始肾小球和小管结构；该胚胎性组织特征有助于鉴别。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-062":{"text":"儿童面部及四肢水肿、低白蛋白、高胆固醇和重度蛋白尿而无血尿，符合微小病变肾病综合征。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-063":{"text":"排尿困难但前列腺活检为良性，提示增生灶位于围尿道的移行区，压迫尿道造成梗阻。","references":[{"title":"Prostate Cancer and Benign Prostatic Hyperplasia","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-064":{"text":"足细胞与基底膜之间的上皮下驼峰样沉积是感染后肾炎的经典电镜征象，常见诱因为A组链球菌感染；选项所列细菌与答案键不符，需复核。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch08-en-single-065":{"text":"红细胞增多且血清促红细胞生成素升高，提示肿瘤异位分泌EPO；肾细胞癌是相关肿瘤来源之一。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-066":{"text":"膜性肾病光镜可见肾小球毛细血管基底膜弥漫增厚；银染常显示上皮下沉积物之间形成的钉突。","references":[{"title":"Membranous Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK559169/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-067":{"text":"弥漫性毛细血管内增生性肾炎常由感染后免疫复合物引起，电镜典型表现为上皮下驼峰样电子致密沉积。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-068":{"text":"急性弥漫性毛细血管内增生性肾炎多为感染后肾炎，儿童通常可恢复；新月体性或膜增生性病变预后较差。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-069":{"text":"多数肾小球肾炎并非细菌直接侵入肾小球，而是免疫复合物或抗体介导；题目E也可能有争议，因为感染后真菌性肾炎可经免疫机制发生。","references":[{"title":"Rapidly Progressive Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK557430/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch08-en-single-070":{"text":"感染后弥漫性增生性肾炎常见双肾弥漫受累、上皮下驼峰和低补体，儿童预后通常较好；“预后极差”不符合一般情况。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-071":{"text":"系膜增生性肾炎的免疫沉积位于系膜区，IgA肾病是常见类型；上皮下驼峰提示感染后肾炎。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-072":{"text":"膜增生性肾炎常见系膜区和内皮下免疫沉积，并伴系膜插入和基底膜双轨样改变。","references":[{"title":"C3 Glomerulopathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK609090/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-073":{"text":"感染后弥漫性毛细血管内增生性肾炎的代表性电镜发现是上皮下驼峰样沉积，可同时有系膜或内皮下沉积。","references":[{"title":"Post-Streptococcal Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK333429/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-074":{"text":"膜性肾病由上皮下免疫复合物沉积引起，基底膜在沉积物间向外长出钉突；选项D描述这一组合。","references":[{"title":"Membranous Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK559169/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-075":{"text":"免疫复合物沉积是许多肾小球肾炎的发病机制，可通过III型超敏反应激活补体并造成炎症。","references":[{"title":"Nephrotic Syndrome","url":"https://www.ncbi.nlm.nih.gov/books/NBK560639/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-076":{"text":"题干问急性肾衰竭总体最常见病因，但临床急性肾损伤常见肾前性因素，不能概括为新月体肾炎。若限定肾实质性急性肾损伤，急性肾小管损伤或坏死才是常见原因；现有选项使答案键A存疑。","references":[{"title":"Acute Kidney Injury","url":"https://www.ncbi.nlm.nih.gov/books/NBK560678/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch08-en-single-077":{"text":"新月体主要由鲍曼囊壁层上皮细胞增生及单核细胞、巨噬细胞进入构成，源于肾小球毛细血管壁破裂。","references":[{"title":"Rapidly Progressive Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK557430/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-078":{"text":"膜性肾病的光镜标志是肾小球基底膜弥漫增厚，免疫复合物位于上皮下；足突融合见于多种蛋白尿性病变。","references":[{"title":"Membranous Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK559169/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-079":{"text":"膜增生性肾炎的细胞增殖主要涉及系膜细胞和毛细血管内皮细胞，细胞外基质增加，形成双轨样基底膜。","references":[{"title":"C3 Glomerulopathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK609090/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-080":{"text":"IgA肾病通常为原发性肾小球肾炎，免疫复合物沉积于系膜；题目答案键标为继发性与标准分类不符，需复核。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch08-en-single-081":{"text":"IgA肾病的诊断性免疫荧光表现为系膜区IgA沉积，常呈颗粒状；其他免疫球蛋白或补体可伴随出现，但不如IgA特异。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-082":{"text":"局灶节段性肾小球硬化常以肾病综合征起病，表现为大量蛋白尿、水肿和低白蛋白；部分病例可伴高血压或血尿。","references":[{"title":"Focal Segmental Glomerulosclerosis","url":"https://www.ncbi.nlm.nih.gov/books/NBK532272/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-083":{"text":"微小病变病通常没有免疫复合物沉积，电镜主要见足细胞足突融合；其余列出的肾炎可有免疫复合物或抗体沉积。","references":[{"title":"Rapidly Progressive Glomerulonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK557430/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-084":{"text":"系膜增生性肾炎以系膜细胞和基质增加、系膜区免疫沉积为主；局灶节段性硬化并非其一般特征。","references":[{"title":"IgA Nephropathy","url":"https://www.ncbi.nlm.nih.gov/books/NBK538214/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-085":{"text":"急性肾盂肾炎以肾盂和肾实质的化脓性炎症为基本病变，常见中性粒细胞进入间质及肾小管。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-086":{"text":"肾盂肾炎主要累及肾小管和间质，并可延及肾盂；仅说间质受累不完整。题目答案键只列间质，可能存在选项或答案问题，需复核。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch08-en-single-087":{"text":"上行性感染先从肾盂黏膜开始，再沿集合管和肾小管扩展至肾实质；肾小球通常不是感染起始部位。","references":[{"title":"Pyelonephritis","url":"https://www.ncbi.nlm.nih.gov/books/NBK543809/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-088":{"text":"儿童最常见的原发肾肿瘤是肾母细胞瘤，又称Wilms肿瘤，通常表现为无痛性腹部肿块。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-089":{"text":"膀胱癌中最常见的是尿路上皮癌，传统名称为移行细胞癌；吸烟和芳香胺暴露是重要危险因素。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-090":{"text":"肾母细胞瘤源于胚胎性原始肾组织，故可形成胚芽、间叶和上皮性小管等不同分化成分。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch08-en-single-091":{"text":"肾母细胞瘤是Wilms肿瘤的同义名称，典型发生于幼儿，组织可呈三相胚胎性结构。","references":[{"title":"Wilms Tumor","url":"https://www.ncbi.nlm.nih.gov/books/NBK442004/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-092":{"text":"肾细胞癌起源于肾实质肾小管上皮；肾盂和输尿管尿路上皮来源肿瘤属于另一类癌。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch08-en-single-093":{"text":"肾细胞癌最常见的组织学亚型是透明细胞癌，细胞质清亮源于脂质和糖原在制片中的溶出。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch08-en-single-094":{"text":"成人最常见的原发性肾肿瘤是肾细胞癌；儿童则以Wilms肿瘤最常见，需结合年龄理解题意。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-095":{"text":"VHL抑癌基因失活可导致透明细胞肾细胞癌，散发病例和遗传性VHL综合征均可涉及该通路。","references":[{"title":"Kidney Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK606505/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch08-en-single-096":{"text":"膀胱尿路上皮癌常见于膀胱侧壁和膀胱三角区；肾盂和输尿管也可发生，但频率较低。","references":[{"title":"Bladder Cancer","url":"https://www.ncbi.nlm.nih.gov/books/NBK536923/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-001":{"text":"宫颈病灶图可见异常腺体结构，结合接触性出血和恶臭分泌物，支持宫颈腺癌；鳞癌不会呈腺体分化。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-002":{"text":"双侧囊性卵巢肿块、乳头突起、间质浸润和砂粒体符合浆液性囊腺癌。浸润证明恶性，成熟畸胎瘤不会形成此类乳头结构。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-003":{"text":"初潮后不久排卵轴尚未成熟，常出现无排卵周期；缺少黄体孕酮会使子宫内膜不规则脱落，而超声正常不支持结构性病变。","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-004":{"text":"肿瘤由合体滋养层样细胞构成并有肺转移，提示绒毛膜癌。合体滋养层分泌hCG，故血清水平升高。","references":[{"title":"Gestational Trophoblastic Disease – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK470267/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-005":{"text":"CIN III累及宫颈上皮全层，虽然尚未突破基底膜，但有进展为浸润癌的高风险。锥切用于切除病变并排除隐匿浸润。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-006":{"text":"会阴疣及挖空细胞是HPV感染的特征。高危型可致宫颈癌前病变，低危型常致尖锐湿疣，其他病原不造成典型挖空细胞。","references":[{"title":"Human Papillomavirus (HPV) Infection – Human Papillomaviruses – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK321770/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-007":{"text":"经期疼痛、不孕和盆腔表面出血灶符合子宫内膜异位症。卵巢病灶反复出血可形成内异症囊肿。","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-008":{"text":"肿物含未成熟间叶、软骨、肌肉和神经上皮，支持未成熟畸胎瘤；成熟型畸胎瘤不应出现未成熟神经组织。","references":[{"title":"Granulosa Theca Cell Tumors of the Ovary – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK565872/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-009":{"text":"HPV16是高危型，未治疗的CIN III可发展为宫颈鳞癌。高级别病变尚未浸润，但持续存在会提高侵袭癌风险。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-010":{"text":"颗粒细胞瘤可分泌雌激素，刺激子宫内膜增生并引起绝经后出血；这比转移或输卵管炎更符合激素效应。","references":[{"title":"Granulosa Theca Cell Tumors of the Ovary – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK565872/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-011":{"text":"绝经后出血提示子宫内膜癌需优先排查，常见组织学类型为腺癌；活检图所示恶性腺体结构与此相符。","references":[{"title":"Postmenopausal Bleeding – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK562188/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-012":{"text":"CIN II属于高级别宫颈上皮内病变，表示宫颈癌风险增加，应规范随访或治疗；这不等同于宫颈炎或息肉。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-013":{"text":"卵巢实性肿块与子宫内膜增生提示雌激素分泌性性索间质瘤。颗粒细胞—卵泡膜细胞瘤可产生雌激素。","references":[{"title":"Granulosa Theca Cell Tumors of the Ovary – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK565872/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-014":{"text":"宫颈癌最常见组织学类型是鳞状细胞癌，通常与持续高危HPV感染相关；腺癌次之","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-015":{"text":"子宫最常见肿瘤是平滑肌瘤，来自肌层平滑肌，常呈界清、漩涡状结节；子宫肉瘤少见","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-016":{"text":"卵巢生殖细胞肿瘤中畸胎瘤最常见，因为生殖细胞可向多个胚层分化；颗粒细胞瘤属于另一细胞来源。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-017":{"text":"散在水肿绒毛并夹有正常绒毛提示部分性葡萄胎，常为三倍体；额外父源染色体可形成69,XXY。","references":[{"title":"Hydatidiform Mole – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK459155/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-018":{"text":"子宫大于孕周、葡萄样水肿绒毛且无胎儿组织，符合完全性葡萄胎；未侵入子宫壁排除侵蚀性葡萄胎。","references":[{"title":"Hydatidiform Mole – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK459155/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-019":{"text":"输卵管局部肿大、急性腹痛及宫腔只有蜕膜，提示异位妊娠。血清妊娠试验仍应阳性","references":[{"title":"Ectopic Pregnancy – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK539860/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-020":{"text":"排出物只有血块和蜕膜、未见绒毛，合并附件区肿块及休克，提示异位妊娠破裂；蜕膜不能证明妊娠在宫内。","references":[{"title":"Ectopic Pregnancy – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK539860/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-021":{"text":"停经八周并且尿hCG阳性，最直接支持妊娠；正常第二性征不排除妊娠，肌瘤或肿瘤不会令试验阳性。","references":[{"title":"Ectopic Pregnancy – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK539860/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-022":{"text":"卵巢肿瘤由梭形细胞组成，提示性索间质来源；上皮肿瘤常形成腺体，生殖细胞瘤可出现胚层分化。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-023":{"text":"题干所述卵巢囊肿含多种成熟组织且无未成熟或神经组织，符合成熟畸胎瘤；答案键标慢性输卵管炎无法解释该形态。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch09-en-single-024":{"text":"闭经、女性第二性征减退及Call-Exner小体提示颗粒细胞瘤。该肿瘤可分泌激素并扰乱月经。","references":[{"title":"Granulosa Theca Cell Tumors of the Ovary – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK565872/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-025":{"text":"腹水和巨大卵巢肿块支持浆液性卵巢癌；本题结论还依赖未提供的大体图，需结合图像核实。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-026":{"text":"卵巢癌家族史及腹膜结节提示浆液性癌；BRCA1参与DNA修复，功能缺陷会增加卵巢癌发生风险。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-027":{"text":"成熟软骨、鳞状上皮和肠腺可见于畸胎瘤，但hCG与AFP同时升高提示混合恶性生殖细胞肿瘤成分。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-028":{"text":"卵巢囊肿衬覆纤毛柱状上皮，符合浆液性肿瘤的输卵管型上皮；黏液性肿瘤通常由非纤毛黏液细胞衬覆。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-029":{"text":"老年男性长期排尿困难、前列腺弥漫增大且PSA正常，符合良性前列腺增生。显微镜可见腺体与间质结节及双层上皮。","references":[{"title":"Benign Prostate Disorders – Endotext – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK279008/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-030":{"text":"无孕激素拮抗的雌激素长期刺激可导致子宫内膜增生，并增加内膜样腺癌风险；腺癌是最常见组织学类型。","references":[{"title":"Endometrial Hyperplasia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560693/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-031":{"text":"附睾及睾丸肉芽肿伴干酪样坏死和朗汉斯巨细胞，是泌尿生殖系结核的典型形态；其他感染一般不形成干酪坏死。","references":[{"title":"Genitourinary Tuberculosis – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK557558/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-032":{"text":"宫颈上皮内瘤变与持续HPV感染密切相关；避孕药或DES暴露不能解释典型CIN细胞学改变。","references":[{"title":"Human Papillomavirus (HPV) Infection – Human Papillomaviruses – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK321770/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-033":{"text":"幼儿睾丸肿块伴Schiller-Duval样结构和AFP阳性，典型为卵黄囊瘤；答案键所列畸胎瘤与线索矛盾，需复核。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch09-en-single-034":{"text":"非典型内膜增生表现为腺体拥挤、芽生和上皮异型；若出现间质浸润则已支持腺癌，而非单纯增生。","references":[{"title":"Endometrial Hyperplasia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560693/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-035":{"text":"乳腺最常见恶性肿瘤是浸润性导管癌（非特殊型）；血管肉瘤、叶状肿瘤和淋巴瘤少见","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-036":{"text":"前列腺PSA升高且活检见密集、单层上皮小腺体，提示腺癌；良性增生通常保留基底细胞层。","references":[{"title":"Urologic Cancers – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-037":{"text":"子宫多发实性肌壁结节伴结节状增大，符合平滑肌瘤；题目要求看大体图，需检查图像以确认。","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-038":{"text":"乳腺最常见良性肿瘤是纤维腺瘤，常见于年轻女性，边界清楚且可活动，由纤维间质与腺管构成。","references":[{"title":"Breast Fibroadenoma – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK535345/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-039":{"text":"儿童睾丸恶性肿瘤常见卵黄囊瘤，可分泌AFP；实性睾丸肿块需要组织学确诊","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-040":{"text":"卵巢肿块混有毛发、皮脂或成熟组织时符合成熟囊性畸胎瘤；其症状可来自囊肿增大或扭转。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-041":{"text":"乳腺浸润性小叶癌常由小而黏附性差的肿瘤细胞单列浸润，呈“靶样”或单行排列，与导管癌腺管结构不同。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-042":{"text":"成年男性睾丸肿瘤若肿瘤标志物或形态显示多种分化，提示混合型生殖细胞肿瘤；治疗按非精原细胞瘤处理。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-043":{"text":"多个子宫肌壁肿块造成尿频和异常出血，符合平滑肌瘤压迫膀胱及宫腔；内膜息肉不会形成多个肌壁结节。","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-044":{"text":"异型细胞局限于乳腺导管内且尚未穿破基底膜，属于导管原位癌；中心坏死常见于粉刺型原位癌。","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-045":{"text":"恶性小腺体缺少基底细胞层并密集排列，支持前列腺腺癌；肿瘤常产生PSA，可辅助诊断和随访。","references":[{"title":"Urologic Cancers – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-046":{"text":"子宫肌层内发现内膜腺体及间质，定义为腺肌症；它常造成痛经、经量增多和子宫增大","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-047":{"text":"乳腺癌组织检测雌激素受体可预测内分泌治疗获益，受体阳性者通常可考虑激素阻断治疗。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-048":{"text":"前列腺硬结及单层小腺体提示腺癌；此肿瘤常发生于外周带，因此直肠指检可能触及","references":[{"title":"Urologic Cancers – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-049":{"text":"内膜组织异位进入子宫肌层是腺肌症，可引起痛经和经量过多；与肌瘤的平滑肌结节不同。","references":[{"title":"Benign Disease of the Uterus – Diseases of the Abdomen and Pelvis 2018–2021","url":"https://www.ncbi.nlm.nih.gov/books/NBK543803/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-050":{"text":"乳头下小肿块伴血性溢液常由导管内乳头状瘤造成；病变位于大乳管，需与乳头状癌鉴别。","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-051":{"text":"前列腺癌多起自外周带，直肠指检可触及硬结；移行带增生更常表现为排尿梗阻","references":[{"title":"Urologic Cancers – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585977/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-052":{"text":"内膜活检图像未附，不能单凭题干确定诊断。若见腺体囊性扩张且无异型，常与无排卵周期相关，需核图。","references":[{"title":"Endometrial Hyperplasia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560693/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-053":{"text":"年轻女性可活动的橡皮样乳房肿块常为纤维腺瘤，组织由纤维间质及被压扁或拉长的腺管组成。","references":[{"title":"Breast Fibroadenoma – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK535345/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-054":{"text":"尿频、夜尿及排尿启动困难伴前列腺增大，提示良性增生；良性增生主要累及移行带并压迫尿道。","references":[{"title":"Benign Prostate Disorders – Endotext – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK279008/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-055":{"text":"不规则子宫出血和内膜腺体囊性扩张提示内膜增生，常由无排卵和持续雌激素作用引起","references":[{"title":"Endometrial Hyperplasia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560693/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-056":{"text":"HER2/neu检测用于判断受体过表达或基因扩增，从而帮助选择抗HER2靶向治疗。","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-057":{"text":"前列腺腺体和间质增生、尿路梗阻症状符合良性前列腺增生，常见于老年男性","references":[{"title":"Benign Prostate Disorders – Endotext – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK279008/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-058":{"text":"内膜腺体囊性扩张且出血不规则，提示子宫内膜增生，常由无排卵造成；细胞异型会进一步增加癌前风险。","references":[{"title":"Endometrial Hyperplasia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560693/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-059":{"text":"纤维腺瘤是良性乳腺肿瘤，通常边界清晰、可活动，预后优于浸润癌","references":[{"title":"Breast Fibroadenoma – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK535345/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-060":{"text":"发热、寒战、尿痛及前列腺触痛肿胀提示急性细菌性前列腺炎；脓性炎症可解释急性全身症状。","references":[{"title":"Acute Bacterial Prostatitis – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK459257/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-061":{"text":"绝经后出血且肥胖、未产提示子宫内膜癌风险；答案键的HPV感染与临床情境不符，应复核。","references":[{"title":"Postmenopausal Bleeding – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK562188/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch09-en-single-062":{"text":"中度或明显导管增生会轻度增加乳腺癌风险；伴非典型增生时风险升高更明显，但仍不等同原位癌。","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-063":{"text":"卵黄囊瘤常分泌甲胎蛋白，血清AFP可用于诊断和监测；hCG则常提示滋养层细胞成分。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-064":{"text":"切片未提供，但题干已明确描述挖空细胞；这是HPV感染的典型细胞学改变，答案可据文字判断。因原图缺失仍标记复核。","references":[{"title":"Human Papillomavirus (HPV) Infection – Human Papillomaviruses – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK321770/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch09-en-single-065":{"text":"乳腺激素受体状态有助于筛选可接受内分泌治疗的患者，也可提供一定预后信息","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-066":{"text":"精原细胞瘤是常见的睾丸恶性生殖细胞肿瘤，多见于青年男性；AFP升高则提示非精原成分。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-067":{"text":"宫颈鳞癌的演进由HPV感染、低级别及高级别上皮内病变发展，最终突破基底膜成为浸润癌。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-068":{"text":"HER2/neu编码跨膜受体酪氨酸激酶；过表达可促进肿瘤生长，并成为靶向治疗依据。","references":[{"title":"Breast Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482286/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-069":{"text":"AFP升高并有未分化恶性细胞支持胚胎性癌或混合性非精原细胞瘤；纯精原细胞瘤不产生AFP。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-070":{"text":"流产组织中水肿绒毛、无胎儿组织及二倍体特征支持完全性葡萄胎；部分性葡萄胎常有胎儿组织和三倍体。","references":[{"title":"Gestational Trophoblastic Disease – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK470267/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-071":{"text":"乳腺导管原位癌仍局限于基底膜内，未侵入间质，故通常比浸润癌预后好","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-072":{"text":"透明胞质的大型肿瘤细胞被含淋巴细胞的纤维隔分开，是精原细胞瘤的经典形态","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch09-en-single-073":{"text":"早孕流产物见部分水肿绒毛和部分正常绒毛，支持部分性葡萄胎；完全性葡萄胎通常弥漫受累且无胎儿组织。","references":[{"title":"Gestational Trophoblastic Disease – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK470267/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-074":{"text":"题目询问乳腺癌预后指标中哪项无预测价值。神经周围侵犯不是常用主要分期因素；此题答案依赖选项比较。","references":[{"title":"Perineural invasion as a risk factor for locoregional recurrence of invasive breast cancer","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8211664/"}],"status":"needs_review","originalAnswer":["A"]},"pathology-ch09-en-single-075":{"text":"肿瘤细胞透明、成片排列，间隔内有淋巴细胞，符合精原细胞瘤；图像仍需与该形态描述核验。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-076":{"text":"乳头状卵巢肿瘤若见砂粒体及间质浸润，支持浆液性腺癌；缺少浸润时才考虑交界性或良性肿瘤。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-077":{"text":"最常见浸润性乳腺癌是导管癌（非特殊型），其肿瘤细胞已突破导管基底膜进入间质","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch09-en-single-078":{"text":"题目要求判读隐睾组织的显微图；隐睾会造成生精小管萎缩并增加生殖细胞肿瘤风险，需查看图确认选项。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch09-en-single-079":{"text":"卵巢乳头状肿瘤伴砂粒体，支持浆液性腺癌；若见间质浸润即可确认恶性，与良性浆液性囊腺瘤区分。","references":[{"title":"Ovarian Cancer – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK585990/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch09-en-single-080":{"text":"乳腺癌腋窝淋巴结转移状态是重要预后指标，阳性结节数量增加通常意味着复发风险上升。","references":[{"title":"Cervical cancer – World Cancer Report","url":"https://www.ncbi.nlm.nih.gov/books/NBK606467/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch09-en-single-081":{"text":"隐睾患者睾丸癌风险升高；腹股沟内睾丸位置异常与生精组织发育障碍有关，需根据图像判断具体病变。","references":[{"title":"Testicular Cancer: Pathogenesis, Diagnosis and Management with Focus on Endocrine Aspects – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK278992/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-001":{"text":"Letterer-Siwe病和骨嗜酸性肉芽肿均属朗格汉斯细胞组织细胞增生症谱系；Kikuchi病则为坏死性淋巴结炎。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-002":{"text":"蕈样肉芽肿是成熟皮肤T细胞淋巴瘤；T淋巴母细胞瘤源于未成熟细胞，其余选项均为B细胞淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-003":{"text":"外周T细胞淋巴瘤通常为成熟T细胞克隆，T细胞受体基因呈克隆性重排；不是前体T细胞肿瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-004":{"text":"鼻腔肿瘤呈血管破坏性生长并表达CD3、CD56和细胞毒分子，符合结外NK/T细胞淋巴瘤；此病常侵袭性强，并非惰性。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-005":{"text":"鼻腔病灶及相应显微图符合结外NK/T细胞淋巴瘤，其细胞常表达CD3、CD56、Granzyme B和TIA-1。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-006":{"text":"蕈样肉芽肿属于成熟皮肤T细胞淋巴瘤；朗格汉斯细胞病虽也累及皮肤，却不是淋巴瘤","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-007":{"text":"儿童颌骨肿块呈星空样、B细胞标记阳性并有t(8;14)，说明MYC易位，符合Burkitt淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-008":{"text":"抗酸染色见红色杆菌并有坏死性肉芽肿，支持淋巴结结核；Kikuchi病不会出现抗酸杆菌。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-009":{"text":"Kikuchi病通常自限，属于组织细胞坏死性淋巴结炎；它不是细菌感染，抗生素并非特异有效治疗。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-010":{"text":"皮肤病灶有Pautrier微脓肿，是蕈样肉芽肿的典型表皮组织学特征；该病为成熟T细胞淋巴瘤。","references":[{"title":"Mycosis fungoides – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK519572/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-011":{"text":"蕈样肉芽肿源于成熟T细胞而非B细胞，常见表皮向性和Pautrier微脓肿；晚期可播散至淋巴结或内脏。","references":[{"title":"Mycosis fungoides – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK519572/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-012":{"text":"猫抓病与猫接触及Bartonella感染相关，可见化脓性肉芽肿及微脓肿，故列出的表现均可成立。","references":[{"title":"Cat scratch disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK482139/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-013":{"text":"儿童颈部淋巴结有肉芽肿和微脓肿，结合题干提示猫抓病；病原Bartonella常引起区域淋巴结炎。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-014":{"text":"结肠肿瘤显微图及腹胀表现支持结外弥漫大B细胞淋巴瘤；该瘤可发生在胃肠道等结外部位。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-015":{"text":"滤泡性淋巴瘤来自生发中心B细胞，常有BCL2表达及惰性病程；“起源于边缘区细胞”是错误说法。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-016":{"text":"散在Reed–Sternberg细胞、以小淋巴细胞为主且缺少中性粒细胞和嗜酸性粒细胞，支持淋巴细胞丰富型经典霍奇金淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-017":{"text":"弥漫大B细胞淋巴瘤既可累及淋巴结，也可发生于结外器官；列出的部位都可能受累，所以无例外项。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-018":{"text":"活检图及CD10、CD20、BCL6阳性支持生发中心B细胞来源的弥漫大B细胞淋巴瘤；临床呈持续淋巴结肿大，也符合其侵袭性病程。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-019":{"text":"嗜酸性肉芽肿属于朗格汉斯细胞组织细胞增生症，病灶内增殖的是朗格汉斯细胞，而非浆细胞或淋巴细胞。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-020":{"text":"白血病骨髓被肿瘤细胞占据，正常造血受抑制，红细胞生成减少而出现贫血；失血或缺铁不是主要机制。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-021":{"text":"慢性淋巴细胞白血病主要见于老年人，属于成熟B细胞克隆性增殖；儿童和婴幼儿罕见","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-022":{"text":"答案键选肝小叶间散在浸润，但ALL更常见门管区聚集；病理分布可有差异，题目答案与经典描述不一致，需复核。","references":[{"title":"ALL肝浸润病例 – PubMed Central","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5923601/"}],"status":"needs_review","originalAnswer":["D"]},"pathology-ch10-en-single-023":{"text":"AML可沿肝窦弥漫浸润，显微镜下表现为肝小叶内散在细胞；这与ALL较常见的门管区聚集有所区别。","references":[{"title":"急性髓系白血病肝浸润 – PubMed Central","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3075178/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-024":{"text":"急性白血病的核心是骨髓内原始及未成熟细胞异常增殖，抑制正常造血；外周白细胞计数不一定升高。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-025":{"text":"白血病相关的经典化学暴露是苯；3,4-苯并芘虽为致癌物，却不是该病常见风险因素，因此选它为“不相关”。","references":[{"title":"苯与白血病风险 – 美国国家癌症研究所","url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/benzene"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-026":{"text":"成熟T细胞及多数T细胞淋巴瘤表达CD2、CD3等T系标记；CD19、CD20、CD10更支持B系。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-027":{"text":"CD10、CD19和CD20支持B细胞分化；CD2、CD3、CD4等则是T细胞常见表型。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-028":{"text":"非霍奇金淋巴瘤中成熟B细胞肿瘤占大多数；具体最常见亚型通常是弥漫大B细胞淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-029":{"text":"经典霍奇金淋巴瘤的诊断依赖Reed–Sternberg细胞；混合细胞型还伴丰富的反应性炎细胞背景。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-030":{"text":"霍奇金淋巴瘤III期定义为膈肌两侧均有淋巴结区域或淋巴样结构受累；仅膈肌一侧属于较低分期。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-031":{"text":"经典霍奇金淋巴瘤常首先累及颈部淋巴结，并可按相邻淋巴结区域顺序扩展","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-032":{"text":"CD20是成熟B细胞常用表面标记，可用于确认B细胞来源；CD3则标记T细胞","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-033":{"text":"MALT淋巴瘤通常生长缓慢，局限时预后较好；弥漫大B细胞或套细胞淋巴瘤更具侵袭性。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-034":{"text":"经典霍奇金淋巴瘤中淋巴细胞丰富型通常预后最好，其次结节硬化型、混合细胞型，淋巴细胞消减型最差。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-035":{"text":"低倍结节结构及高倍腔隙型Reed–Sternberg细胞，结合纤维隔，符合结节硬化型经典霍奇金淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-036":{"text":"淋巴结中多种炎细胞背景和典型Reed–Sternberg细胞支持混合细胞型经典霍奇金淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-037":{"text":"滤泡性、结节硬化型霍奇金及其他淋巴瘤均可呈结节结构；形态模式需结合免疫表型和细胞特征。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-038":{"text":"大型异型细胞弥漫生长且表达CD20、CD45和CD79a，说明成熟B细胞来源，符合弥漫大B细胞淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-039":{"text":"经典霍奇金/Reed–Sternberg细胞通常CD30、CD15阳性，而CD20及CD45阴性；这可与非霍奇金B细胞淋巴瘤区分。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-040":{"text":"鼻中线破坏性肿瘤呈血管破坏和凝固性坏死，符合结外NK/T细胞淋巴瘤；其发生与EB病毒密切相关。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-041":{"text":"CD10、CD19、CD20及BCL2阳性提示生发中心B细胞肿瘤；结合颈部结节病灶，最符合滤泡性淋巴瘤。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-042":{"text":"儿童纵隔肿块伴白细胞增多提示T淋巴母细胞白血病/淋巴瘤，常起源于胸腺前体T细胞。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-043":{"text":"滤泡性淋巴瘤常见t(14;18)，使BCL2异常表达并延长生发中心B细胞存活","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-044":{"text":"套细胞淋巴瘤通常侵袭性较强，预后较差；其常见Cyclin D1过表达和t(11;14)。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch10-en-single-045":{"text":"结外NK/T细胞淋巴瘤常呈血管中心性、血管破坏性生长及广泛坏死，不以结节型生长为典型。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-046":{"text":"淋巴结滤泡及生发中心数量增加，且保留正常结构，更符合反应性滤泡增生；需与单克隆滤泡性淋巴瘤区别。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-047":{"text":"年轻女性颈部无痛淋巴结、胶原纤维隔及腔隙细胞支持结节硬化型经典霍奇金淋巴瘤","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-048":{"text":"旧教材比较费城染色体阳性CML与临床表现相似的阴性病例，阳性者生存更长；此处指历史预后比较，不是TKI疗效。","references":[{"title":"费城染色体与慢性髓性白血病（历史研究）","url":"https://academic.oup.com/jnci/article-pdf/36/4/567/9442105/36-4-567.pdf"}],"status":"explained","originalAnswer":["D"]},"pathology-ch10-en-single-049":{"text":"鼻腔及颌面骨破坏性病灶符合Burkitt淋巴瘤的结外表现；该瘤常见MYC重排及快速增殖。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch10-en-single-050":{"text":"t(8;14)将MYC与免疫球蛋白重链基因连接，是Burkitt淋巴瘤的典型染色体易位。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch10-en-single-051":{"text":"滤泡性淋巴瘤常有t(14;18)导致BCL2过表达，抑制细胞凋亡并造成生发中心B细胞聚集。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch10-en-single-052":{"text":"间变性大细胞淋巴瘤可表达T细胞标志或呈空细胞表型，属于成熟T细胞淋巴瘤；需结合ALK等标志分型。","references":[{"title":"Lymphoma pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560826/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch11-en-single-001":{"text":"肌无力伴前纵隔肿块，活检见含生发中心的反应性淋巴滤泡，符合胸腺滤泡性增生；胸腺瘤则有肿瘤性上皮成分。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch11-en-single-002":{"text":"四枚甲状旁腺均增大且PTH升高，符合慢性低钙刺激所致的继发性增生；腺瘤通常只累及单个腺体。","references":[{"title":"Parathyroid gland pathology – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK546596/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch11-en-single-003":{"text":"甲状腺肿瘤巢间淀粉样物质刚果红阳性，是降钙素沉积的典型线索，提示来源于C细胞的髓样癌。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch11-en-single-004":{"text":"单个包膜性滤泡结节出现包膜侵犯，已满足滤泡癌的诊断条件；滤泡腺瘤必须没有包膜或血管侵犯。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-005":{"text":"甲减、抗TPO阳性及橡皮样甲状腺肿支持桥本甲状腺炎；淋巴细胞浸润伴Hurthle细胞改变最典型。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-006":{"text":"题干列出的嗜铬细胞瘤属于神经内分泌/APUD谱系，故答案键与常见分类不符；乳头状甲状腺癌更像排除项，需复核。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"needs_review","originalAnswer":["E"]},"pathology-ch11-en-single-007":{"text":"降钙素由甲状腺滤泡旁C细胞分泌；髓样癌起源于这些细胞，因此血清降钙素可作为肿瘤标志。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch11-en-single-008":{"text":"乳头状甲状腺癌常低度恶性且预后较好，尤其局限期患者；滤泡癌更常经血行播散","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-009":{"text":"乳头状癌常见透明核、核沟和核内假包涵体，转移多经淋巴道；“倾向血行转移”是错误描述。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-010":{"text":"甲状腺癌中乳头状癌最常见，常由典型核特征确诊；滤泡癌、髓样癌和未分化癌所占比例较低。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-011":{"text":"婴儿生长迟缓、智力发育受损及黏液性水肿表现提示先天或早期甲状腺激素不足，即克汀病。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-012":{"text":"产后泌乳骤停、闭经及多种垂体前叶激素缺乏提示分娩失血后垂体缺血坏死，即Sheehan综合征。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-013":{"text":"骨骺闭合后生长激素过多会使手足、下颌和软组织增大，称肢端肥大症；巨人症发生于骨骺闭合前。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch11-en-single-014":{"text":"桥本甲状腺炎的慢性淋巴细胞浸润可增加甲状腺黏膜相关淋巴组织淋巴瘤风险，是此类淋巴瘤的经典背景。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-015":{"text":"亚急性肉芽肿性甲状腺炎会破坏滤泡并形成肉芽肿，常在病毒感染后出现颈部疼痛及短暂甲状腺毒症。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-016":{"text":"慢性淋巴细胞性甲状腺炎是桥本病，常见滤泡破坏和Hurthle细胞，不是滤泡上皮增生为主。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-017":{"text":"Graves病刺激甲状腺滤泡弥漫增生，形成高柱状上皮及小乳头；与结节性甲状腺肿的局灶结节不同。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch11-en-single-018":{"text":"Graves病的促甲状腺作用来自刺激TSH受体的自身抗体；标准称TSI，答案选TGI的术语可疑，需核对。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"needs_review","originalAnswer":["C"]},"pathology-ch11-en-single-019":{"text":"青春期甲状腺激素需求增加，可能引起弥漫性甲状腺肿；与缺碘性地方性甲状腺肿的背景不同。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch11-en-single-020":{"text":"生长激素腺瘤若发生在骨骺闭合后导致肢端肥大，不会引起骨骺提前闭合；儿童期过量才可造成巨人症。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch11-en-single-021":{"text":"嗜铬细胞瘤释放儿茶酚胺，可致阵发高血压、出汗和心悸；按压肿块可能诱发升压反应，不会典型降压。","references":[{"title":"Pheochromocytoma – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK589700/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch11-en-single-022":{"text":"闭经、溢乳且LH和雌二醇降低提示泌乳素过多抑制促性腺轴；垂体泌乳素瘤可解释这一组合。","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch11-en-single-023":{"text":"阵发性高血压、尿中儿茶酚胺代谢物升高及巢状嗜铬细胞形态，符合肾上腺嗜铬细胞瘤","references":[{"title":"Graves disease and thyroid pathology – Endotext","url":"https://www.ncbi.nlm.nih.gov/books/NBK285567/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-001":{"text":"印度墨汁显示荚膜、黏液卡红染出红色荚膜酵母菌，且患者有AIDS，强烈提示隐球菌性脑膜炎。","references":[{"title":"Cryptococcal Meningitis – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK525986/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch12-en-single-002":{"text":"听神经、面神经及邻近脑干结构集中于桥小脑角；此处肿瘤可同时造成听力下降、耳鸣及同侧面部体征。","references":[{"title":"Cerebellopontine Angle Cancer – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK559116/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch12-en-single-003":{"text":"硬脑膜附着性肿块及旋涡状细胞排列、砂粒体符合脑膜瘤；神经鞘瘤则见Antoni区和Verocay小体。","references":[{"title":"Meningioma – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK560538/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-004":{"text":"朊病毒病的病理特征是灰质神经网和神经元空泡化，形成海绵状改变，通常没有显著炎症反应。","references":[{"title":"Prion Diseases – Basic Neurochemistry – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK27938/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-005":{"text":"胶质母细胞瘤可见坏死和微血管增生，侵袭性最强；其他所列胶质瘤通常恶性程度较低","references":[{"title":"Central Nervous System Tumors Treatment (PDQ®) – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK65982.21/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-006":{"text":"低灌注时大脑动脉分水岭区供血最脆弱，因此对缺氧缺血损伤尤其敏感，可出现边界区梗死。","references":[{"title":"Found Down – Diseases of the Brain, Head and Neck, Spine 2024–2027 – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK608613/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-007":{"text":"高血压性脑出血常累及基底节穿通小动脉供血区，尤其壳核；桥脑、丘脑和小脑也可受累但相对少见。","references":[{"title":"Nontraumatic Intracranial Hemorrhage – Diseases of the Brain, Head and Neck, Spine 2020–2023 – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK554334/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-008":{"text":"Luschka孔阻塞阻断脑室内脑脊液流动，造成非交通性脑积水；脑膜炎和蛛网膜下腔出血则妨碍脑脊液吸收。","references":[{"title":"Hydrocephalus and CSF Disorders – Diseases of the Brain, Head and Neck, Spine 2020–2023 – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK554339/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-009":{"text":"小脑扁桃体疝可压迫延髓并抑制呼吸；眼球运动障碍不是典型同侧定位表现，故该项不符合。","references":[{"title":"Brain Herniation – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK542246/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-010":{"text":"大脑半球肿瘤出现煎蛋样细胞和钙化，符合少突胶质细胞瘤；脑膜瘤多附着于硬脑膜并呈旋涡状。","references":[{"title":"Oligodendroglioma – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK559184/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-011":{"text":"帕金森病运动症状与黑质致密部多巴胺能神经元丢失相关；神经元内可见嗜酸性Lewy小体。","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-012":{"text":"进行性痴呆、皮质萎缩及神经元内丝状缠结和淀粉样斑块符合阿尔茨海默病的经典病理","references":[{"title":"Alzheimer’s Disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK10782/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-013":{"text":"内收障碍伴外展眼震是核间性眼肌麻痹，提示内侧纵束病变，年轻成人常由多发性硬化引起；答案键的垂体瘤需复核。","references":[{"title":"Internuclear Ophthalmoplegia – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK441970/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch12-en-single-014":{"text":"家族性朊病毒病由PRNP基因突变相关，该基因编码朊蛋白；异常折叠蛋白累积导致海绵状脑病。","references":[{"title":"Creutzfeldt-Jakob Disease – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK507860/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-015":{"text":"细菌性化脓性脑膜炎脑脊液常混浊、压力和蛋白升高、糖降低且中性粒细胞增多；淋巴细胞优势不典型。","references":[{"title":"Table 3.1 Typical CSF abnormalities in bacterial and viral meningitis – WHO guidelines – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK614844/table/ch3.tab1/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-016":{"text":"化脓性脑膜炎通常以中性粒细胞为主；大量淋巴细胞更提示病毒、结核或其他慢性感染","references":[{"title":"Bacterial Meningitis – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK470351/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-017":{"text":"HSV脑炎常累及颞叶并见核内包涵体；Negri小体是狂犬病的特征性包涵体，不属于HSV病变。","references":[{"title":"Herpes Simplex Encephalitis – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK557643/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-018":{"text":"吉兰-巴雷综合征是急性炎性周围神经病，不属于朊病毒性海绵状脑病；CJD、库鲁病及疯牛病属此类。","references":[{"title":"Prion Diseases – Basic Neurochemistry – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK27938/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-019":{"text":"海绵状脑病由具有传染性的错误折叠朊蛋白引起，而非DNA或RNA病毒；其病变常缺少炎症。","references":[{"title":"Prion Diseases – Basic Neurochemistry – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK27938/"}],"status":"explained","originalAnswer":["D"]},"pathology-ch12-en-single-020":{"text":"Lewy小体主要与帕金森病相关；阿尔茨海默病的标志是淀粉样斑块、tau缠结和脑萎缩。","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-021":{"text":"帕金森病的神经元胞质Lewy小体由α突触核蛋白聚集形成，是重要组织学标志","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["E"]},"pathology-ch12-en-single-022":{"text":"神经原纤维缠结主要由过度磷酸化tau蛋白构成；β淀粉样蛋白则是老年斑的主要成分。","references":[{"title":"Alzheimer’s Disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK10782/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-023":{"text":"黑质脱色素提示帕金森病而非阿尔茨海默病；后者主要造成皮质萎缩、脑室扩大及斑块缠结。","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["B"]},"pathology-ch12-en-single-024":{"text":"老年斑的β淀粉样蛋白来自淀粉样前体蛋白APP裂解；它与tau构成的神经原纤维缠结是不同病变。","references":[{"title":"Alzheimer’s Disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK10782/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch12-en-single-025":{"text":"高血压导致穿通小动脉壁玻璃样变和微动脉瘤，破裂可引起壳核出血，称Charcot–Bouchard微动脉瘤。","references":[{"title":"Charcot-Bouchard Aneurysm – StatPearls – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK553028/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch12-en-single-026":{"text":"阿尔茨海默病是老年人最常见痴呆病因，常呈缓慢进展的记忆和认知功能下降","references":[{"title":"Alzheimer’s Disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK10782/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-027":{"text":"Hirano小体可在阿尔茨海默病海马神经元中出现；它由肌动蛋白相关细胞骨架蛋白组成。","references":[{"title":"Neuropathology of Alzheimer’s Disease – PMC","url":"https://pmc.ncbi.nlm.nih.gov/articles/2918894/"}],"status":"explained","originalAnswer":["A"]},"pathology-ch12-en-single-028":{"text":"题干答案键给微管蛋白，但老年斑的核心实际为β淀粉样蛋白；微管相关tau是神经原纤维缠结成分，应复核。","references":[{"title":"Alzheimer’s Disease – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK10782/"}],"status":"needs_review","originalAnswer":["B"]},"pathology-ch12-en-single-029":{"text":"帕金森病主要累及黑质多巴胺能神经元，导致基底节运动环路失衡；因此黑质是关键解剖部位。","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["C"]},"pathology-ch12-en-single-030":{"text":"黑质多巴胺能神经元减少是帕金森病的基础病变，解释静止性震颤、强直和运动迟缓","references":[{"title":"Parkinson’s Disease: Etiology, Neuropathology, and Pathogenesis – NCBI Bookshelf","url":"https://www.ncbi.nlm.nih.gov/books/NBK536722/"}],"status":"explained","originalAnswer":["A"]}}};
